const siteBreakdown = computed(() => {
  const colors=['#20d595','#168c68','#3d7562','#6c9b87','#a1b9ad']
  const rows=(summary.value?.siteRanking||[]).map((row:any)=>({...row,energyKwh:Number(row.energyKwh)||0})).filter((row:any)=>row.energyKwh>0)
  const total=rows.reduce((sum:number,row:any)=>sum+row.energyKwh,0)
  const top=rows.slice(0,5), hidden=rows.slice(5).reduce((sum:number,row:any)=>sum+row.energyKwh,0)
  if(hidden) top.push({siteId:'other',siteName:'Lainnya',energyKwh:hidden})
  let cursor=0
  const parts=top.map((row:any,index:number)=>{const percent=total?row.energyKwh/total*100:0,start=cursor;cursor+=percent;return {...row,percent,color:colors[Math.min(index,colors.length-1)],stop:`${colors[Math.min(index,colors.length-1)]} ${start}% ${cursor}%`}})
  return {total,rows:parts,gradient:parts.map((row:any)=>row.stop).join(', ')||'transparent'}
})
const siteDetailAssets = computed(() => { const assets=[...(detail.value?.buildings||[]).flatMap((building:any)=>building.assets||[]),...(detail.value?.meters||[]).map((meter:any)=>meter.asset).filter(Boolean)];return [...new Map(assets.map((asset:any)=>[asset.id,asset])).values()] })
const energyChartPoints = computed(() => {
  const values = series.value.map(point => point.kwh)
  const peak = Math.max(...values, 1)
  return values.map((value, index) => {
    const x = values.length < 2 ? 500 : 30 + index * 940 / (values.length - 1)
    const y = 218 - value / peak * 178
    return `${x},${y}`
  }).join(' ')
})
