    : (detail.value?.meters || []).flatMap((meter: any) => meter.readings || []))
const validDetailReadings = computed(() => detailReadingSource.value
    .filter((reading: any) => reading.quality === 'VALID' && Number.isFinite(Number(reading.value)))
    .sort((a: any, b: any) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()))
const detailSeries = computed(() => validDetailReadings.value.slice(-30))
const detailChartPoints = computed(() => {
  const values = detailSeries.value.map((reading: any) => Number(reading.value))
  if (values.length < 2) return ''
  const min = Math.min(...values), max = Math.max(...values), spread = max - min || 1
  return values.map((value, index) => `${values.length < 2 ? 500 : 24 + index * 952 / (values.length - 1)},${212 - (value - min) / spread * 160}`).join(' ')
})
