    { label: 'Format', value: detail.value?.format || '—', note: 'Export format' },
    { label: 'Rows', value: detail.value?.rowCount ?? detail.value?.recordCount ?? '—', note: 'Snapshot records' },
    { label: 'Created', value: detail.value?.createdAt ? new Date(detail.value.createdAt).toLocaleDateString('id-ID') : '—', note: detail.value?.expiresAt ? `Expires ${new Date(detail.value.expiresAt).toLocaleDateString('id-ID')}` : 'Report snapshot' }
  ]
  return [
    { label: 'Latest reading', value: latest ? `${Number(latest.value).toLocaleString('id-ID')} ${latest.unit || 'kWh'}` : '—', note: latest ? 'validated reading' : 'No reading yet' },
    { label: 'Data quality', value: total ? `${(valid / total * 100).toFixed(1)}%` : '—', note: total ? `${valid} of ${total} loaded readings valid` : 'No reading history' },
    { label: page.value === 'Sites' ? 'Facility' : 'Site', value: siteName || '—', note: page.value === 'Sites' ? detail.value?.status || 'Site' : 'Assigned facility' },
    { label: 'Last updated', value: updatedAt ? new Date(updatedAt).toLocaleTimeString('id-ID', { timeZone: detail.value?.site?.timezone || detail.value?.timezone || 'Asia/Jakarta', hour: '2-digit', minute: '2-digit' }) + ' WIB' : '—', note: updatedAt ? new Date(updatedAt).toLocaleDateString('id-ID') : 'Waiting for data' }
  ]
})
