function displayCell(record: WorkspaceRecord, key: string) {
  const item = record as any
  const value = item[key] ?? item.payload?.[key] ?? item.rule?.[key]
  if (key === 'siteId' && value) return item.site?.name || sites.value.find(site => site.id === value)?.name || value
  if (key === 'createdAt' || key === 'scheduledAt' || key === 'effectiveFrom' || key === 'effectiveTo' || key === 'startDate' || key === 'endDate' || key === 'periodStart') return value ? new Date(value).toLocaleDateString('id-ID') : '—'
  if (key === 'permissions' && Array.isArray(value)) return value.join(', ')
  if (key === 'active' && typeof value === 'boolean') return value ? 'Aktif' : 'Nonaktif'
  if (value && typeof value === 'object') return JSON.stringify(value)
  return value ?? '—'
}
