 / CRITICAL)'}] }
const filteredAlerts = computed(() => records.value.filter(r => { const rule = r.rule as any; return `${r.message || ''} ${rule?.name || ''}`.toLowerCase().includes(search.value.toLowerCase()) && (alertStatus.value === 'ALL' || r.status === alertStatus.value) && (alertSeverity.value === 'ALL' || rule?.severity === alertSeverity.value) }))
const filteredRecords = computed(() => records.value.filter(record => JSON.stringify(record).toLowerCase().includes(search.value.trim().toLowerCase())))
