async function createTariff() { busy.value=true; error.value=''; try { const rates=tariffForm.value.tariffType==='TOU'?[{startMinute:0,endMinute:Number(tariffForm.value.splitMinute),unitRate:Number(tariffForm.value.rateBefore)},{startMinute:Number(tariffForm.value.splitMinute),endMinute:1440,unitRate:Number(tariffForm.value.rateAfter)}]:[]; await request('/tariffs',{method:'POST',body:JSON.stringify({name:tariffForm.value.name,currency:'IDR',tariffType:tariffForm.value.tariffType,unitRate:Number(tariffForm.value.unitRate),fixedCharge:Number(tariffForm.value.fixedCharge),taxPercent:Number(tariffForm.value.taxPercent),rates,effectiveFrom:tariffForm.value.effectiveFrom,...(tariffForm.value.effectiveTo?{effectiveTo:tariffForm.value.effectiveTo}:{})})}); await loadTariffData(); showForm.value=false } catch(e) { error.value=(e as Error).message } finally { busy.value=false } }
