async function runCostAnalysis() { busy.value=true; error.value=''; try { const query=scopedQuery({periodStart:`${costFilters.value.periodStart}T00:00:00.000Z`,periodEnd:`${costFilters.value.periodEnd}T23:59:59.999Z`,...(costFilters.value.siteId?{siteId:costFilters.value.siteId}:{})}); costResult.value=await request<any>(`/cost-analysis?${query}`) } catch(e) { costResult.value=null; error.value=(e as Error).message } finally { busy.value=false } }
async function runReport() { busy.value=true; error.value=''; try { reportCreated.value=await request<any>('/reports',{method:'POST',body:JSON.stringify({type:reportForm.value.type,periodStart:`${reportForm.value.periodStart}T00:00:00.000Z`,periodEnd:`${reportForm.value.periodEnd}T23:59:59.999Z`,...(reportForm.value.siteId?{siteId:reportForm.value.siteId}:{}),...(reportForm.value.buildingId?{buildingId:reportForm.value.buildingId}:{}),...(reportForm.value.meterId?{meterId:reportForm.value.meterId}:{}),timezone:reportForm.value.timezone,granularity:reportForm.value.granularity,...(reportForm.value.emissionFactorId?{emissionFactorId:reportForm.value.emissionFactorId}:{}),format:reportForm.value.format})}); await loadRecords('Reports') } catch(e) { error.value=(e as Error).message } finally { busy.value=false } }
async function runEmissionEstimate() { busy.value=true; error.value=''; try { const query=scopedQuery({siteId:emissionForm.value.siteId,periodStart:`${emissionForm.value.periodStart}T00:00:00.000Z`,periodEnd:`${emissionForm.value.periodEnd}T23:59:59.999Z`,...(emissionForm.value.factorId?{factorId:emissionForm.value.factorId}:{})}); emissionEstimate.value=await request<any>(`/emissions/estimate?${query}`) } catch(e) { emissionEstimate.value=null; error.value=(e as Error).message } finally { busy.value=false } }
