async function approveBaseline(id:string) { const notes=window.prompt('Catatan persetujuan baseline (minimal 2 karakter):'); if(!notes)return; busy.value=true; try { await request(`/baselines/${id}/approve`,{method:'POST',body:JSON.stringify({notes})}); await loadRecords('Baselines & Targets') } catch(e) { error.value=(e as Error).message } finally { busy.value=false } }
