async function createMaintenance() { busy.value=true; try { await request(`/meters/${detail.value.id}/maintenance`,{method:'POST',body:JSON.stringify({...maintenanceForm.value,scheduledAt:maintenanceForm.value.scheduledAt?new Date(maintenanceForm.value.scheduledAt).toISOString():undefined,assignedTo:maintenanceForm.value.assignedTo||undefined})}); records.value=await request<any[]>(`/meters/${detail.value.id}/maintenance`); showForm.value=false } catch(e) { error.value=(e as Error).message } finally { busy.value=false } }
async function maintenanceTransition(id:string,status:string) { const outcome=status==='COMPLETED'?window.prompt('Hasil pekerjaan wajib diisi:'):undefined; if(status==='COMPLETED'&&!outcome)return; try { await request(`/meter-maintenance/${id}/status`,{method:'PATCH',body:JSON.stringify({status,...(outcome?{outcome}:{})})}); records.value=await request<any[]>(`/meters/${detail.value.id}/maintenance`) } catch(e) { error.value=(e as Error).message } }
function fileToBase64(file:File) { return new Promise<string>((resolve,reject)=>{ const reader=new FileReader(); reader.onerror=()=>reject(new Error('File tidak dapat dibaca.')); reader.onload=()=>resolve(String(reader.result).split(',')[1]||''); reader.readAsDataURL(file) }) }
async function uploadEvidence(event:Event,kind:'audit'|'maintenance',maintenanceId='') { const target=event.target; const input=target instanceof HTMLInputElement?target:target instanceof HTMLFormElement?target.querySelector<HTMLInputElement>('input[type="file"]'):null; const file=input?.files?.[0]; if(!file)return; if(file.size>5*1024*1024){error.value='Batas file bukti 5 MB.';return}; const mime=file.type as 'application/pdf'|'image/jpeg'|'image/png'; if(!['application/pdf','image/jpeg','image/png'].includes(mime)){error.value='Gunakan PDF, PNG, atau JPEG.';return}; busy.value=true; try { await request(kind==='audit'?`/audits/${detail.value.id}/evidence`:`/meter-maintenance/${maintenanceId}/evidence`,{method:'POST',body:JSON.stringify({fileName:file.name,contentType:mime,contentBase64:await fileToBase64(file)})}); if(kind==='audit') await openDetail('Energy Audits',detail.value.id,false); else records.value=await request<any[]>(`/meters/${detail.value.id}/maintenance`) } catch(e) { error.value=(e as Error).message } finally { busy.value=false;if(input)input.value=''} }
async function reviseReading(readingId:string) { const revision=readingRevision.value[readingId]; if(!revision)return; try { await request(`/meters/${detail.value.id}/readings/${readingId}/revisions`,{method:'POST',body:JSON.stringify(revision)}); await openDetail('Meters',detail.value.id,false) } catch(e) { error.value=(e as Error).message } }
async function restore(): Promise<User | null> {
  try { user.value = await request<User>('/auth/me'); workspaceStore.setSession(user.value) } catch { user.value = null; workspaceStore.setSession(null); return null }
  sites.value = []; meters.value = []; summary.value = null; series.value = []
  if (user.value?.scope === 'ASSIGNED_SITES' && !user.value.siteIds.includes(monitorFilters.value.siteId)) monitorFilters.value.siteId = user.value.siteIds[0] || ''
  try {
    await refresh()
    if (workspaceStore.hasAnyPermission(['monitor.read','dashboard.read'])) await loadMonitoringData()
  } catch (e) { error.value = (e as Error).message }
  return user.value
}
async function signIn() { busy.value = true; error.value = ''; try { await request('/auth/login', { method: 'POST', body: JSON.stringify(login.value) }); await restore(); login.value.password = ''; const destination=typeof route.query.redirect==='string' ? route.query.redirect : '/dashboard'; await router.replace(destination) } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
