async function applyPasswordReset() { busy.value=true; error.value=''; try { if(resetPassword.value.password!==resetPassword.value.confirm) throw new Error('Konfirmasi kata sandi tidak sama.'); const token=typeof route.query.token==='string'?route.query.token:''; await request('/auth/reset-password',{method:'POST',body:JSON.stringify({token,password:resetPassword.value.password})}); authNotice.value='Kata sandi berhasil diubah. Silakan masuk.'; await router.replace('/login') } catch(e) { error.value=(e as Error).message } finally { busy.value=false } }
async function acceptInvitation() { busy.value=true; error.value=''; try { const token=typeof route.query.token==='string'?route.query.token:''; const payload={token,...(!user.value?{password:invitationPassword.value}:{})}; await request('/auth/accept-invitation',{method:'POST',body:JSON.stringify(payload)}); if(user.value) { await request('/auth/logout',{method:'POST'}); user.value=null; workspaceStore.setSession(null) }; authNotice.value='Undangan diterima. Silakan masuk dengan akun Anda.'; await router.replace('/login') } catch(e) { error.value=(e as Error).message } finally { busy.value=false } }
