function closeForm() { if(!showForm.value)return; showForm.value=false; if(route.path==='/meters/new') void router.replace('/meters'); if(route.path==='/buildings/new') void router.replace('/buildings'); if(editingRecordId.value){void router.replace('/buildings/'+editingRecordId.value);editingRecordId.value=null} }
function navigate(item: string, updateUrl = true) { if (updateUrl) void router.push(paths[item] || '/dashboard'); detail.value=null; detailReadings.value=[]; readingCursor.value=null; page.value = item; search.value = updateUrl ? '' : String(route.query.search || ''); currentPage.value=updateUrl ? 1 : Math.max(1, Number(route.query.page) || 1); pageSize.value=updateUrl ? pageSize.value : ([25,50,100].includes(Number(route.query.pageSize)) ? Number(route.query.pageSize) : 25); sortState.value=updateUrl ? {key:'createdAt',direction:'desc'} : {key:typeof (route.query.sortBy ?? route.query.sort) === 'string' ? String(route.query.sortBy ?? route.query.sort) : 'createdAt',direction:(route.query.sortOrder ?? route.query.direction) === 'asc' ? 'asc' : 'desc'}; error.value = ''; showForm.value = false; records.value=[]; if(item==='Dashboard'||item==='Monitoring') { if(workspaceStore.hasAnyPermission(['monitor.read','dashboard.read'])) void loadMonitoringData().catch(e=>error.value=(e as Error).message); if(item==='Dashboard') void loadRecentActivity() }; if(item==='Sites'||item==='Meters')void loadCatalog(); else if (endpoints[item] || item==='Cost Analysis' || item==='Organization Settings') loadRecords(item); if(item==='Meters' && workspaceStore.hasAnyPermission(['asset.manage','meter.configure'])) void request<typeof meterAssets.value>('/assets').then(items => { meterAssets.value = items }).catch(e => { error.value = (e as Error).message }); if(item==='Data Imports') { void request<typeof importSources.value>('/data-sources').then(items => { importSources.value = items.filter(source => source.type === 'CSV' && source.status === 'ACTIVE') }).catch(e => { error.value = (e as Error).message }); if(user.value?.role==='ADMIN') void loadQuarantine(); watchImportJobs() }; if(item==='Alerts') loadAlerts(); if(item==='Data Quality') { if(user.value?.scope!=='ORGANIZATION' && !dataQualityFilters.value.siteId) dataQualityFilters.value.siteId=sites.value[0]?.id||''; void loadDataQuality() }; if(item==='Notifications') void loadNotifications(); if(item==='Users') void loadUserAdminData(); if(item==='Roles & Permissions') void loadRoleData(); if(item==='Integrations') void loadIntegrations(); if(item==='Analytics & Forecast') void loadForecastRuns(); if(item==='Emissions' || item==='Reports') void loadEmissionFactors() }
async function copySecret(value: string) { try { await navigator.clipboard.writeText(value); authNotice.value='Token berhasil disalin.' } catch { error.value='Clipboard tidak tersedia. Salin token dari kolom secara manual.' } }
async function openDetail(item: string, id: string, updateUrl = true) { if (item === 'Sites') siteDetailTab.value='Summary'; if (updateUrl) { void router.push(`${paths[item]}/${encodeURIComponent(id)}`); return } try { const endpoint = item === 'Data Imports' ? 'reading-imports' : (endpoints[item] || paths[item].slice(1)); detail.value=await request<any>(`/${endpoint}/${id}`); if(item==='Meters'){const first=await request<any>(`/meters/${id}/readings?limit=100`);detailReadings.value=first.items;readingCursor.value=first.nextCursor}else{detailReadings.value=[];readingCursor.value=null}; if (item === 'Energy Audits' && user.value?.role === 'ADMIN') auditUsers.value=await request('/users') } catch(e) { error.value=(e as Error).message } }
async function loadMoreReadings() { if(!detail.value?.id||!readingCursor.value||loadingReadings.value)return;loadingReadings.value=true;try{const next=await request<any>(`/meters/${detail.value.id}/readings?limit=100&cursor=${encodeURIComponent(readingCursor.value)}`);detailReadings.value.push(...next.items);readingCursor.value=next.nextCursor}catch(e){error.value=(e as Error).message}finally{loadingReadings.value=false} }
function syncLocation() { const path=route.path.replace(/\/$/, '') || '/dashboard'; const exact=Object.entries(paths).find(([,p]) => p===path); if(path === '/profile') { navigate('My Profile',false); return } if(path === '/forbidden') { navigate('Access Denied',false); return } if(path === '/meters/new') { navigate('Meters',false); showForm.value=true; return } if(path === '/buildings/new') { navigate('Buildings',false); showForm.value=true; return } const buildingEdit=path.match(/^\/buildings\/([^/]+)\/edit$/); if(buildingEdit) { navigate('Buildings',false); void openBuildingEdit(decodeURIComponent(buildingEdit[1])); return } if(exact) { navigate(exact[0],false); return } const subroute=path.match(/^\/meters\/([^/]+)\/(configuration-history|maintenance)$/); if(subroute) { navigate('Meters',false); void loadMeterSubpage(decodeURIComponent(subroute[1]),subroute[2]); return } const match=Object.entries(paths).filter(([name]) => ['Sites','Buildings','Assets','Meters','Data Imports','Energy Audits','Reports','Alerts'].includes(name)).find(([,p]) => path.startsWith(p+'/')); if(match) { navigate(match[0],false); void openDetail(match[0],decodeURIComponent(path.slice(match[1].length+1)),false) } else navigate('Dashboard',false) }
