async function loadRecords(item:string) { loadingRecords.value=true;try { if (item === 'Organization Settings') { const organization = await cachedRequest<{name:string}>('organization','/organization'); organizationForm.value.name = organization.name; return } if(item==='Tariffs & Cost') { await loadTariffData(); records.value=tariffs.value; return } if(item==='Cost Analysis') { await runCostAnalysis(); return } const endpoint=endpoints[item]; if(!endpoint) throw new Error(`Modul ${item} belum memiliki endpoint domain.`); let url=`/${endpoint}`;if(serverPagedPages.has(item)){const query=new URLSearchParams({page:String(currentPage.value),pageSize:String(pageSize.value),sortBy:sortState.value.key,sortOrder:sortState.value.direction,...(search.value.trim()?{search:search.value.trim()}:{})});url+=`?${query}`}const loaded=await queryClient.fetchQuery({queryKey:['api',user.value?.id,user.value?.organization?.id,`list:${item}:${url}`],queryFn:()=>request<any>(url),staleTime:0});if(serverPagedPages.has(item)&&loaded&&!Array.isArray(loaded)&&Array.isArray(loaded.items)){records.value=loaded.items;serverPageActive.value=true;serverRecordCount.value=loaded.pagination.total;serverPageCount.value=Math.max(1,loaded.pagination.pageCount)}else{records.value=loaded;serverPageActive.value=false;serverRecordCount.value=records.value.length;serverPageCount.value=1} } catch(e) { error.value=(e as Error).message } finally { loadingRecords.value=false } }
