async function save() { error.value = ''; busy.value = true; try { const site = page.value === 'Sites', newMeter = route.path === '/meters/new'; const payload=site?{...siteForm.value,latitude:siteForm.value.latitude===''?null:Number(siteForm.value.latitude),longitude:siteForm.value.longitude===''?null:Number(siteForm.value.longitude),managerId:siteForm.value.managerId||null,emissionRegion:siteForm.value.emissionRegion||null}:{...meterForm.value,serialNumber:meterForm.value.serialNumber||undefined,assetId:meterForm.value.assetId||undefined,installedAt:meterForm.value.installedAt?new Date(meterForm.value.installedAt).toISOString():undefined,rolloverValue:meterForm.value.rolloverValue||undefined}; await request(site && editingSite.value ? `/sites/${detail.value.id}` : site ? '/sites' : '/meters', { method: site && editingSite.value ? 'PATCH' : 'POST', body: JSON.stringify(payload) }); await refresh(); showForm.value = false; if (newMeter) await router.replace('/meters'); if (site && editingSite.value) await openDetail('Sites',detail.value.id,false); editingSite.value=false } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
