watch([search,meterSite,meterStatus,currentPage],([nextSearch,nextSite,nextStatus,nextPage],[oldSearch,oldSite,oldStatus,oldPage])=>{const filtersChanged=nextSearch!==oldSearch||nextSite!==oldSite||nextStatus!==oldStatus;if(filtersChanged&&nextPage===oldPage&&nextPage!==1){currentPage.value=1;return}if(filtersChanged||nextPage!==oldPage)reloadCurrentList()})
