watch([currentPage,pageSize,sortState],()=>{if(!serverPagedPages.has(page.value)&&page.value!=='Sites'&&page.value!=='Meters')return;const query:Record<string,any>={...route.query,page:String(currentPage.value),pageSize:String(pageSize.value),sortBy:sortState.value.key,sortOrder:sortState.value.direction};delete query.sort;delete query.direction;void router.replace({path:route.path,query})},{deep:true})
watch(monitorFilters, filters => { const query:Record<string,any>={...route.query}; for(const key of ['siteId','buildingId','meterId','days','metric','bucket','comparePrevious']) delete query[key]; for(const [key,value] of Object.entries(filters)) if(value!=='' && value!==false) query[key]=String(value); void router.replace({path:route.path,query}); if(['Dashboard','Monitoring'].includes(page.value)) void loadMonitoringData().catch(e=>error.value=(e as Error).message) },{deep:true})
watch(search,value=>{const query:Record<string,any>={...route.query};if(value.trim())query.search=value.trim();else delete query.search;void router.replace({path:route.path,query})})
watch([meterSite,meterStatus],()=>{if(page.value!=='Meters')return;const query:Record<string,any>={...route.query};if(meterSite.value==='ALL')delete query.siteId;else query.siteId=meterSite.value;if(meterStatus.value==='ALL')delete query.status;else query.status=meterStatus.value;void router.replace({path:route.path,query})})
let liveRefreshTimer: ReturnType<typeof setInterval> | undefined, eventStream: EventSource | undefined
onMounted(async () => { if(typeof route.query.search==='string')search.value=route.query.search;if(typeof route.query.siteId==='string'&&route.path==='/meters')meterSite.value=route.query.siteId;if(typeof route.query.status==='string'&&route.path==='/meters')meterStatus.value=route.query.status; for(const key of ['siteId','buildingId','meterId','days','metric','bucket','comparePrevious'] as const) { const value=route.query[key]; if(typeof value==='string' && value!=='') (monitorFilters.value as any)[key]=key==='days'?Number(value):key==='comparePrevious'?value==='true':value }; const current=await restore(); if(current) { profileForm.value.fullName=current.fullName; syncLocation(); if(workspaceStore.hasAnyPermission(['notification.read','alert.read','monitor.read'])) { eventStream=new EventSource('/api/v1/events'); eventStream.addEventListener('updates',()=>{ if(page.value==='Alerts') void loadAlerts(); if(page.value==='Notifications') void loadNotifications(); if(['Dashboard','Monitoring'].includes(page.value)) void loadMonitoringData().catch(e=>error.value=(e as Error).message) }) }; liveRefreshTimer=setInterval(()=>{ if(['Dashboard','Monitoring'].includes(page.value) && workspaceStore.hasAnyPermission(['monitor.read','dashboard.read'])) void loadMonitoringData().catch(e=>error.value=(e as Error).message) },30_000) } })
onUnmounted(()=>{ if(liveRefreshTimer) clearInterval(liveRefreshTimer); if(importRefreshTimer)clearInterval(importRefreshTimer); eventStream?.close() })
</script>

<template>
  <main v-if="!user" class="login-screen"><section class="login-card"><div class="mb-9 flex items-center text-xl font-extrabold tracking-[-.7px] text-[#f2faf5]"><ArrowUpRight class="mr-1 size-5 text-primary" /> EnergiTrack</div><template v-if="route.path === '/forgot-password'"><p class="eyebrow">PEMULIHAN AKUN</p><h1>Lupa kata sandi?</h1><p class="muted">Masukkan email. Jika akun ditemukan, instruksi reset akan dikirim.</p><form @submit.prevent="sendPasswordReset"><label>Email<Input v-model="forgotEmail" type="email" required autocomplete="email" /></label><p v-if="authNotice" class="notice">{{ authNotice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary full" :disabled="busy">Kirim instruksi</button><button type="button" class="secondary full" @click="router.push('/login')">Kembali ke login</button></form></template><template v-else-if="route.path === '/reset-password'"><p class="eyebrow">PEMULIHAN AKUN</p><h1>Buat kata sandi baru</h1><form @submit.prevent="applyPasswordReset"><label>Kata sandi baru<Input v-model="resetPassword.password" type="password" minlength="12" maxlength="200" required autocomplete="new-password" /></label><label>Ulangi kata sandi<Input v-model="resetPassword.confirm" type="password" minlength="12" required autocomplete="new-password" /></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary full" :disabled="busy">Simpan kata sandi</button></form></template><template v-else-if="route.path === '/accept-invitation'"><p class="eyebrow">UNDANGAN ORGANISASI</p><h1>Terima undangan</h1><p class="muted">Tautan berlaku 24 jam. Pengguna baru perlu membuat kata sandi minimal 12 karakter.</p><form @submit.prevent="acceptInvitation"><label>Kata sandi baru<Input v-model="invitationPassword" type="password" minlength="12" maxlength="200" required autocomplete="new-password" /></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary full" :disabled="busy">Terima undangan</button></form></template><template v-else><p class="eyebrow">ENERGY MANAGEMENT PLATFORM</p><h1>Selamat datang kembali</h1><p class="muted">Masuk untuk mengakses ruang kerja energi Anda.</p><form @submit.prevent="signIn"><label>Email<Input v-model="login.email" type="email" required autocomplete="username" placeholder="nama@perusahaan.com" /></label><label>Kata sandi<Input v-model="login.password" type="password" required autocomplete="current-password" placeholder="Masukkan kata sandi" /></label><p v-if="authNotice" class="notice">{{ authNotice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary full" :disabled="busy">{{ busy ? 'Memproses…' : 'Masuk' }}</button><RouterLink class="auth-link" to="/forgot-password">Lupa kata sandi?</RouterLink></form></template></section></main>
  <main v-else-if="route.path === '/accept-invitation'" class="login-screen"><section class="login-card"><div class="mb-9 flex items-center text-xl font-extrabold tracking-[-.7px] text-[#f2faf5]"><ArrowUpRight class="mr-1 size-5 text-primary" /> EnergiTrack</div><p class="eyebrow">UNDANGAN ORGANISASI</p><h1>Terima undangan</h1><p class="muted">Masuk sebagai {{ user.email }} untuk mengaitkan undangan ke akun ini.</p><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary full" :disabled="busy" @click="acceptInvitation">Terima undangan</button></section></main><main v-else-if="page === 'Access Denied'" class="login-screen"><section class="login-card"><div class="mb-9 flex items-center text-xl font-extrabold tracking-[-.7px] text-[#f2faf5]"><ArrowUpRight class="mr-1 size-5 text-primary" /> EnergyTrack</div><h1>Akses tidak tersedia</h1><p class="muted">Role akun Anda tidak memiliki permission untuk halaman ini.</p><button class="primary full" @click="navigate('Dashboard')">Kembali ke dashboard</button></section></main><WorkspaceLayout v-else :user="user" :visible-sections="visibleSections" :page="page" :page-labels="pageLabels" v-model:menu="menu" v-model:menu-search="menuSearch" @navigate="navigate" @sign-out="signOut"><div class="content mx-auto w-full max-w-[1530px] px-4 pb-16 pt-[25px] min-[551px]:px-[22px] min-[901px]:px-[31px]"><div v-if="error" class="toast error-toast" role="alert" aria-live="assertive">{{ error }}<button v-if="serverPagedPages.has(page) || page === 'Sites' || page === 'Meters'" class="secondary" @click="reloadCurrentList">Coba lagi</button><button class="icon-button" aria-label="Tutup pesan" @click="error=''">×</button></div><div v-if="authNotice && page!=='Notifications' && page!=='Integrations'" class="toast success-toast" role="status" aria-live="polite">{{ authNotice }}<button class="icon-button" aria-label="Tutup pesan" @click="authNotice=''">×</button></div><div class="breadcrumb">Energy Operations / {{ displayPage }}</div><div :class="['page-heading', { 'catalog-heading': ['Sites','Buildings','Assets','Meters'].includes(page) }]"><div><h1>{{ displayPage }}</h1><p class="muted">{{ page === 'Dashboard' ? 'Pantau dan kelola data energi di seluruh fasilitas Anda.' : page === 'Sites' ? 'Kelola fasilitas dan lokasi operasional Anda.' : page === 'Meters' ? 'Kelola perangkat meter dan konfigurasi pengukuran.' : descriptions[page] || 'Data energi dan operasional.' }}</p></div></div>
  <section v-if="detail && !['Configuration History','Meter Maintenance'].includes(page)" class="detail-page"><button class="secondary detail-back" @click="navigate(page)">← Kembali ke {{ pageLabels[page] || page }}</button><div class="panel record-hero"><div><span class="eyebrow">RECORD DETAIL · {{ displayPage.toUpperCase() }}</span><h2 class="detail-title">{{ detail.name || detail.code || detail.title || detail.fileName || detail.message }}</h2><p class="muted">{{ detail.code || detail.fileName || detail.message || 'Informasi detail' }}</p></div><span v-if="detail.status" class="badge">{{ detail.status }}</span><button v-if="page === 'Buildings' && canCreatePage" class="secondary" @click="startBuildingEdit">Edit building</button></div><div v-if="detailPageLabels[page]" class="kpis detail-kpis"><article v-for="metric in detailKpis" :key="metric.label" class="panel kpi"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong><small>{{ metric.note }}</small></article></div><section v-if="detailPageLabels[page]" class="panel detail-history"><div class="detail-history-heading"><div><h2>{{ detailActivityTitle }}</h2><p class="muted">Validated meter readings · latest 30 records</p></div><span class="badge">{{ detailSeries.length }} readings</span></div><div v-if="detailChartPoints" class="detail-chart"><svg viewBox="0 0 1000 240" role="img" aria-label="Validated energy reading history"><line v-for="y in [52,104,156,208]" :key="y" x1="24" :y1="y" x2="976" :y2="y"/><polyline :points="detailChartPoints"/></svg><div class="detail-chart-labels"><span>{{ detailSeries[0] ? new Date(detailSeries[0].timestamp).toLocaleDateString('id-ID') : '' }}</span><span>{{ detailSeries.at(-1) ? new Date(detailSeries.at(-1).timestamp).toLocaleDateString('id-ID') : '' }}</span></div></div><div v-else-if="detailActivityItems.length" class="detail-activity-list"><article v-for="item in detailActivityItems" :key="item.id" class="detail-row"><strong>{{ item.title }}</strong><p class="muted">{{ item.at ? new Date(item.at).toLocaleString('id-ID') : item.note }}</p><p v-if="item.at" class="muted">{{ item.note }}</p></article></div><div v-else class="detail-chart-empty">Belum ada data riwayat untuk record ini.</div></section><section class="panel detail-panel"><h2 v-if="page!=='Sites'">Record overview</h2><div v-if="page!=='Sites'" class="detail-grid"><div v-for="(value,key) in detail" :key="key" v-show="!['id','organizationId','meters','findings','site'].includes(String(key)) && typeof value !== 'object'"><span>{{ key }}</span><strong>{{ value ?? '—' }}</strong></div></div><SiteDetailTabs v-if="page === 'Sites'" :detail="detail" :can-edit="canCreatePage" v-model:active-tab="siteDetailTab" :assets="siteDetailAssets" @edit="startSiteEdit" @open-meter="id => openDetail('Meters', id)" /><template v-if="page === 'Meters'"><nav class="detail-tabs" role="tablist" aria-label="Bagian detail meter"><button role="tab" aria-selected="true" class="active">Readings</button><button role="tab" aria-selected="false" @click="router.push(`/meters/${detail.id}/configuration-history`)">Configuration History</button><button role="tab" aria-selected="false" v-if="workspaceStore.hasAnyPermission(['meter.maintain','maintenance.manage','maintenance.assigned'])" @click="router.push(`/meters/${detail.id}/maintenance`)">Maintenance</button></nav><div class="form-actions"><button v-if="canCreatePage" v-for="status in meterTransitions[detail.status] || []" :key="status" class="secondary" @click="setMeterStatus(status)">{{ status }}</button><button v-if="canCreatePage" class="secondary" @click="configForm={sourceType:detail.sourceType,intervalMinutes:detail.intervalMinutes,multiplier:Number(detail.multiplier),rolloverValue:detail.rolloverValue||'',effectiveFrom:new Date().toISOString().slice(0,16),reason:''};showForm=true">Versi konfigurasi baru</button></div><h2>Bacaan terakhir · {{ detail.site?.timezone }}</h2><div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>NILAI</th><th>UNIT</th><th>KUALITAS</th></tr></thead><tbody><tr v-for="r in detailReadings" :key="r.id"><td>{{ new Date(r.timestamp).toLocaleString('id-ID', {timeZone:detail.site.timezone}) }}</td><td>{{ r.value }}</td><td>{{ r.unit }}</td><td>{{ r.quality }}<details v-if="workspaceStore.hasAnyPermission(['reading.import'])"><summary>Revisi</summary><input v-model="(readingRevision[r.id] ||= {value:'',quality:r.quality,reason:''}).value" aria-label="Nilai mentah bacaan baru" placeholder="Nilai mentah baru"><select v-global-select v-model="(readingRevision[r.id] ||= {value:'',quality:r.quality,reason:''}).quality"><option>VALID</option><option>ESTIMATED</option><option>SUSPECT</option><option>INVALID</option></select><input v-model="(readingRevision[r.id] ||= {value:'',quality:r.quality,reason:''}).reason" placeholder="Alasan koreksi" required><button class="secondary" @click="reviseReading(r.id)">Simpan revisi</button></details><small v-for="revision in r.revisions||[]" :key="revision.id" class="muted">Versi {{ revision.previousValue }} → {{ revision.correctedValue }} · {{ revision.reason }} · {{ revision.actor?.fullName }}</small></td></tr></tbody></table><div v-if="!detailReadings.length" class="empty">Belum ada bacaan.</div></div><div v-if="readingCursor" class="form-actions"><button class="secondary" :disabled="loadingReadings" @click="loadMoreReadings">{{ loadingReadings ? 'Memuat…' : 'Muat bacaan lebih lama' }}</button></div></template><template v-if="page === 'Data Imports'"><h2>Kesalahan baris</h2><p v-for="e in detail.errors?.rows || []" :key="e.row">Baris {{ e.row }}: {{ e.message }}</p><p class="muted">Duplikat: {{ detail.errors?.duplicates ?? 0 }}</p></template><template v-if="page === 'Alerts'"><h2>Riwayat tindakan</h2><div v-for="event in detail.events" :key="event.id" class="detail-row">{{ new Date(event.createdAt).toLocaleString('id-ID') }} · {{ event.details?.from }} → {{ event.details?.to }} · {{ event.details?.note || '—' }}</div><p v-if="!detail.events?.length" class="muted">Belum ada tindakan.</p><div v-if="availableAlertTransitions(detail.status).length"><label>Catatan (wajib untuk penyelesaian)<textarea v-model="alertNote"></textarea></label><div class="form-actions"><button v-for="status in availableAlertTransitions(detail.status)" :key="status" class="secondary" @click="transitionAlert(status)">{{ status }}</button></div></div></template><template v-if="page === 'Reports'"><p class="muted">Snapshot konsumsi tervalidasi · UTC · batas akhir eksklusif</p><p><a class="primary download" :href="`/api/v1/reports/${detail.id}/download`">Unduh CSV</a></p></template><template v-if="page === 'Energy Audits'"><h2>Bukti audit</h2><div class="table-wrap"><table><thead><tr><th>NAMA FILE</th><th>TIPE</th><th>UKURAN</th><th>SCAN</th><th>AKSI</th></tr></thead><tbody><tr v-for="evidence in detail.evidence||[]" :key="evidence.id"><td>{{ evidence.fileName }}</td><td>{{ evidence.contentType }}</td><td>{{ evidence.sizeBytes }} byte</td><td>{{ evidence.scanProvider }} · {{ evidence.scannedAt ? new Date(evidence.scannedAt).toLocaleString('id-ID') : '—' }}</td><td><a :href="`/api/v1/audits/${detail.id}/evidence/${evidence.id}`">Unduh</a></td></tr></tbody></table><div v-if="!detail.evidence?.length" class="empty">Belum ada bukti audit.</div></div><form v-if="workspaceStore.hasAnyPermission(['audit.evidence.manage','audit.submit','audit.approve']) && ['DRAFT','SCHEDULED','IN_PROGRESS','REVISION_REQUIRED'].includes(detail.status)" @submit.prevent="uploadEvidence($event,'audit')"><label>Tambah bukti (PDF/JPEG/PNG, maksimum 5 MB)<input type="file" accept="application/pdf,image/jpeg,image/png" required></label><button class="secondary" :disabled="busy">Unggah bukti audit</button></form><h2>Temuan</h2><p v-if="!detail.findings?.length" class="muted">Belum ada temuan.</p><div v-for="f in detail.findings" :key="f.id" class="detail-row"><strong>{{ f.severity }} · {{ f.observation }}</strong><p class="muted">Rekomendasi: {{ f.recommendation }}</p><div v-for="a in f.actions" :key="a.id" class="detail-row">Tindakan: {{ a.status }} · {{ auditUsers.find(u => u.id === a.ownerId)?.fullName || a.ownerId }} · {{ a.dueDate?.slice(0,10) }} <span v-if="a.outcome"> · {{ a.outcome }}</span> <a v-if="a.evidenceUrl" :href="a.evidenceUrl" target="_blank" rel="noopener noreferrer">Bukti</a></div></div><form v-if="canCreatePage && detail.status !== 'CLOSED' && detail.findings?.length" @submit.prevent="correctiveAction(false)"><h2>Tambah tindakan korektif</h2><label>Temuan<select v-global-select v-model="correctiveForm.findingId" required><option value="" disabled>Pilih temuan</option><option v-for="f in detail.findings" :key="f.id" :value="f.id">{{ f.observation }}</option></select></label><label>Penanggung jawab<select v-global-select v-model="correctiveForm.ownerId" required><option value="" disabled>Pilih pengguna</option><option v-for="u in auditUsers.filter(x => x.active)" :key="u.id" :value="u.id">{{ u.fullName }}</option></select></label><label>Tenggat<input v-model="correctiveForm.dueDate" type="date" required></label><button class="secondary">Tambah tindakan</button></form><form v-if="canCreatePage && detail.status !== 'CLOSED' && detail.findings?.some((f:any) => f.actions.some((a:any) => a.status === 'OPEN'))" @submit.prevent="correctiveAction(true)"><h2>Tutup tindakan korektif</h2><label>Tindakan<select v-global-select v-model="closureForm.actionId" required><option value="" disabled>Pilih tindakan</option><template v-for="f in detail.findings" :key="f.id"><option v-for="a in f.actions.filter((item:any) => item.status === 'OPEN')" :key="a.id" :value="a.id">{{ f.observation }} · {{ a.dueDate?.slice(0,10) }}</option></template></select></label><label>Hasil<textarea v-model="closureForm.outcome" required minlength="2"></textarea></label><label>URL bukti<input v-model="closureForm.evidenceUrl" type="url" required></label><button class="secondary">Tutup tindakan</button></form><form v-if="canAddAuditFinding && ['DRAFT','SCHEDULED','IN_PROGRESS','REVISION_REQUIRED'].includes(detail.status)" @submit.prevent="auditAction('finding')"><h2>Tambah temuan</h2><label>Severity<select v-global-select v-model="findingForm.severity"><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></label><label>Observasi<textarea v-model="findingForm.observation" required minlength="2"></textarea></label><label>Rekomendasi<textarea v-model="findingForm.recommendation" required minlength="2"></textarea></label><button class="primary">Simpan temuan</button></form><div v-if="availableAuditTransitions(detail.status).length"><label>Komentar status (wajib untuk revisi)<input v-model="auditComment"></label><div class="form-actions"><button v-for="status in availableAuditTransitions(detail.status)" :key="status" class="secondary" @click="auditAction('transition', status)">{{ status }}</button></div></div></template></section></section><template v-else-if="page === 'Dashboard'"><DashboardScreen :monitor-filters="monitorFilters" :summary="summary" :series="series" :series-unit="seriesUnit" :sites="sites" :meters="meters" :site-breakdown="siteBreakdown" :recent-activity="recentActivity" :can-read-audit-log="workspaceStore.hasAnyPermission(['auditlog.read'])" :navigate="navigate" /></template>
  <template v-else-if="page === 'Sites' || page === 'Meters'"><section class="panel"><div class="table-toolbar"><div><h2>Daftar {{ page }}</h2><p class="muted">{{ catalogTotal }} data terdaftar</p></div><div class="catalog-filters"><input v-model="search" class="search" :placeholder="`Cari ${page.toLowerCase()}...`" :aria-label="`Cari ${page}`"><select v-global-select v-if="page === 'Meters'" v-model="meterSite" aria-label="Filter site"><option value="ALL">Semua site</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select><select v-global-select v-if="page === 'Meters'" v-model="meterStatus" aria-label="Filter status meter"><option value="ALL">Semua status</option><option>PENDING</option><option>TESTING</option><option>ONLINE</option><option>OFFLINE</option><option>MAINTENANCE</option><option>RETIRED</option></select><button v-if="canCreatePage" class="primary" @click="startCreate">+ Tambah data {{ page }}</button></div></div><div v-if="loadingCatalog" class="loading-skeleton" role="status"><i v-for="n in 4" :key="n"></i></div><div class="table-wrap"><table v-if="page === 'Sites'"><thead><tr><th class="sortable" @click="toggleSort('code')">{{ sortedLabel('code','KODE SITE') }}</th><th class="sortable" @click="toggleSort('name')">{{ sortedLabel('name','NAMA SITE') }}</th><th class="sortable" @click="toggleSort('type')">{{ sortedLabel('type','TIPE') }}</th><th>ZONA WAKTU</th><th class="sortable" @click="toggleSort('status')">{{ sortedLabel('status','STATUS') }}</th></tr></thead><tbody><tr v-for="site in pagedSites" :key="site.id" class="clickable" @click="openDetail('Sites', site.id)"><td class="accent">{{ site.code }}</td><td>{{ site.name }}<small>{{ site.address }}</small></td><td>{{ site.type }}</td><td>{{ site.timezone }}</td><td><span class="badge">{{ site.status }}</span></td></tr></tbody></table><table v-else><thead><tr><th class="sortable" @click="toggleSort('code')">{{ sortedLabel('code','KODE METER') }}</th><th>SITE</th><th class="sortable" @click="toggleSort('meterType')">{{ sortedLabel('meterType','TIPE') }}</th><th class="sortable" @click="toggleSort('metric')">{{ sortedLabel('metric','METRIK') }}</th><th>BACAAN TERAKHIR</th><th>WAKTU BACAAN</th><th class="sortable" @click="toggleSort('status')">{{ sortedLabel('status','STATUS') }}</th></tr></thead><tbody><tr v-for="meter in pagedMeters" :key="meter.id" class="clickable" @click="openDetail('Meters', meter.id)"><td class="accent">{{ meter.code }}</td><td>{{ meter.site.name }}</td><td>{{ meter.meterType }}</td><td>{{ meter.metric }} · {{ meter.unit }}</td><td>{{ meter.readings[0] ? `${meter.readings[0].value} ${meter.readings[0].unit} · ${meter.readings[0].quality}` : '—' }}</td><td>{{ meter.readings[0] ? new Date(meter.readings[0].timestamp).toLocaleString('id-ID', {timeZone:meter.site.timezone}) + ' · ' + meter.site.timezone : '—' }}</td><td><span class="badge">{{ meter.status }}</span></td></tr></tbody></table><div v-if="!catalogTotal" class="empty">{{ search ? 'Tidak ada hasil yang cocok.' : 'Belum ada data. Tambahkan data untuk memulai.' }}</div><div v-if="listPageCount>1" class="form-actions pagination"><button class="secondary" :disabled="currentPage===1" @click="currentPage--">Sebelumnya</button><span>Halaman {{ currentPage }} / {{ listPageCount }}</span><button class="secondary" :disabled="currentPage>=listPageCount" @click="currentPage++">Berikutnya</button></div></div></section></template>
  <section v-else-if="page === 'Data Imports'" class="import-layout"><div class="panel import-panel"><h2>Unggah bacaan meter (CSV)</h2><p class="muted">Kolom: meterCode, timestamp (ISO 8601), metric, rawValue, unit, externalReadingId (opsional). Format lama dengan value tetap didukung. Maksimum 10 MB atau 5.000 baris.</p><label>Sumber CSV *<select v-global-select v-model="importSourceId" required @change="importPreview=null"><option value="" disabled>Pilih sumber aktif</option><option v-for="source in importSources" :key="source.id" :value="source.id">{{ source.name }}</option></select></label><label class="upload">Pilih file CSV<input type="file" accept=".csv,text/csv" @change="selectImport"></label><div class="form-actions"><button class="secondary" :disabled="!importSourceId || !importText || busy" @click="importPreview ? (importPreview=null) : runImport()">{{ importPreview ? 'Batalkan pratinjau' : 'Buat pratinjau' }}</button><button class="primary" :disabled="!importPreview || busy" @click="runImport">{{ busy ? 'Memproses…' : 'Konfirmasi & antrekan impor' }}</button></div><div v-if="importPreview" class="notice">{{ importPreview.valid }} valid dari {{ importPreview.total }} baris · {{ importPreview.rejected }} ditolak <p v-for="item in importPreview.errors" :key="item.row">Baris {{ item.row }}: {{ item.message }}</p></div></div><div v-if="user.role==='ADMIN'" class="panel import-panel"><div class="table-toolbar"><div><h2>Karantina data</h2><p class="muted">Baris ditolak disimpan untuk ditinjau. Periksa site, meter, timestamp, nilai, dan unit sebelum dilepas.</p></div><button class="secondary" @click="loadQuarantine">Muat ulang</button></div><div class="table-wrap"><table><thead><tr><th>FILE / BARIS</th><th>ALASAN</th><th>DATA</th><th>AKSI</th></tr></thead><tbody><tr v-for="row in quarantinedRows" :key="row.id"><td>{{ row.fileName }} · {{ row.payload?.rowNumber }}</td><td>{{ row.reason }}</td><td>{{ JSON.stringify(row.payload?.values) }}</td><td><button class="secondary" @click="beginQuarantineRelease(row)">Koreksi & lepas</button></td></tr></tbody></table><div v-if="!quarantinedRows.length" class="empty">Tidak ada baris karantina terbuka.</div></div></div><div class="panel import-panel"><h2>Riwayat impor</h2><div class="table-wrap"><table><thead><tr><th>FILE</th><th>DITERIMA</th><th>DITOLAK</th><th>STATUS</th><th>WAKTU</th></tr></thead><tbody><tr v-for="r in records" :key="r.id" class="clickable" @click="openDetail('Data Imports',r.id)"><td>{{ (r as any).fileName }}</td><td>{{ (r as any).accepted }}</td><td>{{ (r as any).rejected }}</td><td>{{ r.status }}</td><td>{{ new Date(r.createdAt || '').toLocaleString('id-ID') }}</td></tr></tbody></table><div v-if="!records.length" class="empty">Belum ada impor.</div></div></div></section><section v-else-if="page === 'Alerts'" class="alert-list"><div class="alert-toolbar"><input v-model="search" aria-label="Cari alert" placeholder="Cari alert..."><select v-global-select v-model="alertSeverity" aria-label="Severity"><option value="ALL">Semua severity</option><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select><select v-global-select v-model="alertStatus" aria-label="Status alert"><option value="ALL">Semua status</option><option>OPEN</option><option>ACKNOWLEDGED</option><option>INVESTIGATING</option><option>RESOLVED</option><option>FALSE_POSITIVE</option></select><button v-if="canCreatePage" class="primary" @click="navigate('Alert Rules')">Aturan alert</button></div><article v-for="alert in filteredAlerts" :key="alert.id" class="panel alert-card"><div><h2>{{ (alert.rule as any)?.severity }} · {{ (alert.rule as any)?.name }}</h2><p>{{ alert.message }}</p><small class="muted">{{ new Date(alert.triggeredAt || '').toLocaleString('id-ID') }}</small></div><span class="badge">{{ alert.status }}</span><button class="secondary" @click="openDetail('Alerts',alert.id)">Buka insiden</button></article><div v-if="!filteredAlerts.length" class="panel empty">{{ records.length ? 'Tidak ada alert yang cocok dengan filter.' : 'Belum ada alert.' }}</div></section><section v-else-if="page === 'Tariffs & Cost'" class="admin-workspace"><section class="panel"><div class="table-toolbar"><div><h2>Tarif energi</h2><p class="muted">Versi tarif FLAT atau TOU dengan biaya tetap, pajak, dan tanggal efektif.</p></div></div><form class="filter-row" @submit.prevent="createTariff"><label>Nama tarif<input v-model="tariffForm.name" minlength="2" required></label><label>Tipe<select v-global-select v-model="tariffForm.tariffType"><option>FLAT</option><option>TOU</option></select></label><label v-if="tariffForm.tariffType === 'FLAT'">Tarif IDR/kWh<input v-model.number="tariffForm.unitRate" type="number" min="0" step="any" required></label><template v-else><label>Tarif 00:00–batas<input v-model.number="tariffForm.rateBefore" type="number" min="0" step="any" required></label><label>Batas menit dari 00:00<input v-model.number="tariffForm.splitMinute" type="number" min="1" max="1439" required></label><label>Tarif batas–24:00<input v-model.number="tariffForm.rateAfter" type="number" min="0" step="any" required></label></template><label>Biaya tetap bulanan<input v-model.number="tariffForm.fixedCharge" type="number" min="0" step="any"></label><label>Pajak %<input v-model.number="tariffForm.taxPercent" type="number" min="0" max="100" step="any"></label><label>Berlaku mulai<input v-model="tariffForm.effectiveFrom" type="date" required></label><label>Berlaku sampai<input v-model="tariffForm.effectiveTo" type="date"></label><button class="primary" :disabled="busy || !canCreatePage">Simpan tarif</button></form><div class="table-wrap"><table><thead><tr><th>NAMA</th><th>JENIS</th><th>RATE</th><th>BIAYA TETAP</th><th>PAJAK</th><th>MASA BERLAKU</th><th>JADWAL TOU</th></tr></thead><tbody><tr v-for="tariff in tariffs" :key="tariff.id"><td>{{ tariff.name }}</td><td>{{ tariff.tariffType }}</td><td>{{ tariff.unitRate }} {{ tariff.currency }}/kWh</td><td>{{ tariff.fixedCharge }}</td><td>{{ tariff.taxPercent }}%</td><td>{{ tariff.effectiveFrom?.slice(0,10) }} – {{ tariff.effectiveTo?.slice(0,10) || 'seterusnya' }}</td><td>{{ (tariff.rates||[]).map((r:any)=>`${Math.floor(r.startMinute/60).toString().padStart(2,'0')}:${(r.startMinute%60).toString().padStart(2,'0')}–${r.endMinute===1440?'24:00':`${Math.floor(r.endMinute/60).toString().padStart(2,'0')}:${(r.endMinute%60).toString().padStart(2,'0')}`} · ${r.unitRate}`).join(' | ') || '—' }}</td></tr></tbody></table><div v-if="!tariffs.length" class="empty">Belum ada tarif.</div></div></section><section class="panel"><h2>Tetapkan tarif ke meter</h2><form class="filter-row" @submit.prevent="assignTariff"><label>Meter energi<select v-global-select v-model="assignmentForm.meterId" required><option value="" disabled>Pilih meter</option><option v-for="meter in meters.filter(m=>m.metric==='ENERGY_IMPORT')" :key="meter.id" :value="meter.id">{{ meter.code }} · {{ meter.site.name }}</option></select></label><label>Tarif<select v-global-select v-model="assignmentForm.tariffId" required><option value="" disabled>Pilih tarif</option><option v-for="tariff in tariffs" :key="tariff.id" :value="tariff.id">{{ tariff.name }} · {{ tariff.tariffType }}</option></select></label><label>Mulai efektif<input v-model="assignmentForm.effectiveFrom" type="date" required></label><label>Sampai<input v-model="assignmentForm.effectiveTo" type="date"></label><button class="primary" :disabled="busy">Tetapkan</button></form><div class="table-wrap"><table><thead><tr><th>METER</th><th>TARIF</th><th>MULAI</th><th>AKHIR</th></tr></thead><tbody><tr v-for="a in tariffAssignments" :key="a.id"><td>{{ meters.find(m=>m.id===a.meterId)?.code || a.meterId }}</td><td>{{ a.name }}</td><td>{{ a.effectiveFrom?.slice(0,10) }}</td><td>{{ a.effectiveTo?.slice(0,10) || '—' }}</td></tr></tbody></table></div></section></section>
<section v-else-if="page === 'Cost Analysis'" class="panel analysis-results cost-analysis"><h2>Analisis biaya energi</h2><p class="muted">Biaya memakai bacaan tervalidasi, penugasan tarif efektif, biaya tetap prorata, pajak, dan indikator kelengkapan.</p><form class="filter-row" @submit.prevent="runCostAnalysis"><label>Site<select v-global-select v-model="costFilters.siteId"><option value="">Semua site dalam cakupan</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label><label>Mulai<input v-model="costFilters.periodStart" type="date" required></label><label>Akhir<input v-model="costFilters.periodEnd" type="date" required></label><button class="primary" :disabled="busy">Hitung biaya</button></form><div v-if="costResult" class="kpis"><div class="panel kpi"><span>Energi</span><strong>{{ costResult.energyKwh ?? '—' }} kWh</strong></div><div class="panel kpi"><span>Estimasi biaya</span><strong>{{ costResult.estimatedCostIdr ?? 'Belum terharga' }} IDR</strong></div><div class="panel kpi"><span>Kelengkapan</span><strong>{{ costResult.completenessPercent ?? '—' }}%</strong></div><div class="panel kpi"><span>Bacaan</span><strong>{{ costResult.observedReadings }}/{{ costResult.expectedReadings }}</strong></div></div><p v-if="costResult" class="notice">{{ costResult.note }}</p><div v-if="costResult?.meters?.length" class="table-wrap"><table><thead><tr><th>METER</th><th>ENERGI</th><th>BIAYA</th><th>KELENGKAPAN</th></tr></thead><tbody><tr v-for="row in costResult.meters" :key="row.meterId"><td>{{ meters.find(m=>m.id===row.meterId)?.code || row.meterId }}</td><td>{{ row.energyKwh }} kWh</td><td>{{ row.estimatedCostIdr ?? 'Belum terharga' }} IDR</td><td>{{ row.completenessPercent ?? '—' }}%</td></tr></tbody></table></div></section>
<section v-else-if="page === 'Emissions'" class="panel report-form-panel"><h2>Estimasi emisi</h2><p class="muted">Faktor dipilih otomatis menurut region dan tahun site atau dapat dipilih manual.</p><form class="filter-row" @submit.prevent="runEmissionEstimate"><label>Site<select v-global-select v-model="emissionForm.siteId" required><option value="" disabled>Pilih site</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label><label>Faktor emisi (opsional)<select v-global-select v-model="emissionForm.factorId"><option value="">Otomatis dari region/tahun</option><option v-for="factor in emissionFactors" :key="factor.id" :value="factor.id">{{ factor.region }} · {{ factor.applicableYear }} · {{ factor.factor }} {{ factor.unit }}</option></select></label><label>Mulai<input v-model="emissionForm.periodStart" type="date" required></label><label>Akhir<input v-model="emissionForm.periodEnd" type="date" required></label><button class="primary" :disabled="busy">Hitung emisi</button></form><section v-if="emissionEstimate" class="panel kpi"><span>Total emisi · {{ emissionEstimate.region }} · {{ emissionEstimate.timezone }}</span><strong>{{ emissionEstimate.estimatedTco2e ?? emissionEstimate.totalKgCo2e ?? '—' }} tCO₂e</strong><p class="muted">{{ emissionEstimate.note || 'Berdasarkan bacaan tervalidasi dan faktor yang berlaku.' }}</p></section></section>
<section v-else-if="page === 'Access Denied'" class="panel unavailable"><h2>Akses tidak tersedia</h2><p class="muted">Akun Anda tidak memiliki permission untuk membuka layar ini. Hubungi administrator organisasi untuk meminta akses.</p><button class="secondary" @click="navigate('Dashboard')">Kembali ke dashboard</button></section>
<section v-else-if="page === 'Configuration History' || page === 'Meter Maintenance'" class="panel"><div class="table-toolbar"><div><h2>{{ page }}</h2><p class="muted">{{ detail?.code }} · {{ detail?.site?.name }}</p></div><button v-if="page === 'Meter Maintenance' && workspaceStore.hasAnyPermission(['meter.maintain','maintenance.manage','maintenance.assigned'])" class="primary" @click="maintenanceForm={category:'PREVENTIVE',title:'',scheduledAt:'',assignedTo:''};showForm=true">Jadwalkan pemeliharaan</button></div><nav class="detail-tabs" role="tablist" aria-label="Bagian detail meter"><button role="tab" aria-selected="false" @click="router.push(`/meters/${detail.id}`)">Readings</button><button role="tab" :aria-selected="page==='Configuration History'" :class="{active:page==='Configuration History'}" @click="router.push(`/meters/${detail.id}/configuration-history`)">Configuration History</button><button role="tab" :aria-selected="page==='Meter Maintenance'" :class="{active:page==='Meter Maintenance'}" v-if="workspaceStore.hasAnyPermission(['meter.maintain','maintenance.manage','maintenance.assigned'])" @click="router.push(`/meters/${detail.id}/maintenance`)">Maintenance</button></nav><template v-if="page === 'Configuration History'"><div class="table-wrap"><table><thead><tr><th v-for="(value,key) in (records[0] || {})" :key="key">{{ String(key).toUpperCase() }}</th></tr></thead><tbody><tr v-for="row in records" :key="row.id"><td v-for="(value,key) in row" :key="key">{{ typeof value === 'object' ? JSON.stringify(value) : value }}</td></tr></tbody></table><div v-if="!records.length" class="empty">Belum ada riwayat konfigurasi.</div></div></template><template v-else><article v-for="item in records" :key="item.id" class="panel"><div class="table-toolbar"><div><h3>{{ item.title }} <span class="badge">{{ item.status }}</span></h3><p class="muted">{{ item.category }} · {{ item.scheduledAt ? new Date(item.scheduledAt).toLocaleString('id-ID') : 'Tanpa jadwal' }} · Ditugaskan ke {{ item.assignedTo || 'belum ditetapkan' }}</p><p>{{ item.workNotes || item.outcome || 'Belum ada catatan pekerjaan.' }}</p></div><div class="form-actions"><button v-if="item.status==='SCHEDULED'" class="secondary" @click="maintenanceTransition(item.id,'IN_PROGRESS')">Mulai</button><button v-if="item.status==='IN_PROGRESS'" class="secondary" @click="maintenanceTransition(item.id,'COMPLETED')">Selesaikan</button><button v-if="item.status==='SCHEDULED'" class="secondary" @click="maintenanceTransition(item.id,'CANCELLED')">Batalkan</button></div></div><div class="detail-row" v-for="evidence in item.evidence||[]" :key="evidence.id"><a :href="`/api/v1/meter-maintenance/${item.id}/evidence/${evidence.id}`">{{ evidence.fileName }}</a> · {{ evidence.sizeBytes }} byte · {{ evidence.scanProvider }}</div><form v-if="['IN_PROGRESS','COMPLETED'].includes(item.status)" @submit.prevent><label>Tambah bukti pemeliharaan (PDF/JPEG/PNG)<input type="file" accept="application/pdf,image/jpeg,image/png" @change="uploadEvidence($event,'maintenance',item.id)"></label></form></article><div v-if="!records.length" class="empty">Belum ada jadwal pemeliharaan.</div></template></section>
<section v-else-if="page === 'Baselines & Targets' || page === 'Energy Targets'" class="panel"><div class="table-toolbar"><div><h2>{{ page === 'Baselines & Targets' ? 'Baseline energi' : 'Target energi' }}</h2><p class="muted">{{ page === 'Baselines & Targets' ? 'Versioning, normalisasi, persetujuan, dan perbandingan konsumsi aktual.' : 'Kemajuan target memakai bacaan tervalidasi pada kalender lokal site.' }}</p></div><button v-if="canCreatePage" class="primary" @click="startCreate">+ Tambah {{ page === 'Energy Targets' ? 'target' : 'baseline' }}</button></div><div class="table-wrap"><table><thead><tr><th>SITE</th><th>{{ page === 'Energy Targets' ? 'TARGET (kWh)' : 'BASELINE (kWh)' }}</th><th>PERIODE</th><th v-if="page==='Baselines & Targets'">VERSI / STATUS</th><th v-else>PROGRESS</th><th>AKSI</th></tr></thead><tbody><tr v-for="record in records" :key="record.id"><td>{{ sites.find(site=>site.id===record.siteId)?.name || record.siteId }}</td><td>{{ record.value ?? record.targetValue }}</td><td>{{ String(record.startDate).slice(0,10) }} – {{ String(record.endDate).slice(0,10) }}</td><td v-if="page==='Baselines & Targets'">V{{ record.version }} · {{ record.status }}<small v-if="record.denominator">Normalisasi {{ record.denominator }} {{ record.denominatorUnit }}</small></td><td v-else>{{ targetProgress[record.id]?.actualKwh ?? 'Belum dihitung' }} / {{ record.targetValue }} kWh <small v-if="targetProgress[record.id]?.completionPercent">{{ targetProgress[record.id].completionPercent }}% tercapai</small></td><td><div class="form-actions"><button v-if="page==='Energy Targets' || record.status==='APPROVED'" class="secondary" @click="loadProgress(page==='Energy Targets'?'target':'baseline',record.id)">{{ page==='Energy Targets'?'Hitung progress':'Bandingkan aktual' }}</button><button v-if="page==='Baselines & Targets' && record.status==='DRAFT' && canCreatePage" class="secondary" @click="approveBaseline(record.id)">Setujui</button><button v-if="page==='Baselines & Targets' && record.status==='APPROVED' && canCreatePage" class="secondary" @click="reviseBaseline(record)">Buat revisi</button></div><small v-if="baselineProgress[record.id]">Aktual {{ baselineProgress[record.id].actualKwh ?? '—' }} kWh · varians {{ baselineProgress[record.id].variancePercent ?? '—' }}%</small></td></tr></tbody></table><div v-if="!records.length" class="empty">Belum ada baseline atau target.</div></div></section>
<section v-else-if="page === 'Reports'" class="admin-workspace"><section class="panel report-form-panel"><h2>Report Builder</h2><p class="muted">Pilih jenis laporan, cakupan, zona waktu, granularitas, dan format. Pembuatan laporan diproses sebagai job backend.</p><form class="filter-row" @submit.prevent="runReport"><label>Jenis laporan<select v-global-select v-model="reportForm.type"><option value="ENERGY">Consumption</option><option value="COST">Cost</option><option value="QUALITY">Data Quality</option><option value="ALERTS">Alerts</option><option value="AUDIT">Audit</option><option value="EMISSIONS">Emissions</option></select></label><label>Site (opsional)<select v-global-select v-model="reportForm.siteId"><option value="">Semua site sesuai akses</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label><label>Gedung<select v-global-select v-model="reportForm.buildingId"><option value="">Semua gedung</option><option v-for="building in buildings.filter(b=>!reportForm.siteId || b.siteId===reportForm.siteId)" :key="building.id" :value="building.id">{{ building.name }}</option></select></label><label>Meter<select v-global-select v-model="reportForm.meterId"><option value="">Semua meter</option><option v-for="meter in meters.filter(m=>!reportForm.siteId || m.site.id===reportForm.siteId)" :key="meter.id" :value="meter.id">{{ meter.code }}</option></select></label><label>Periode mulai<input v-model="reportForm.periodStart" type="date" required></label><label>Periode akhir<input v-model="reportForm.periodEnd" type="date" required></label><label>Zona waktu<select v-global-select v-model="reportForm.timezone"><option>Asia/Jakarta</option><option>Asia/Makassar</option><option>Asia/Jayapura</option><option>UTC</option></select></label><label>Granularitas<select v-global-select v-model="reportForm.granularity"><option>HOUR</option><option>DAY</option><option>WEEK</option><option>MONTH</option></select></label><label>Faktor emisi<select v-global-select v-model="reportForm.emissionFactorId"><option value="">Otomatis per tahun</option><option v-for="factor in emissionFactors" :key="factor.id" :value="factor.id">{{ factor.region }} · {{ factor.applicableYear }}</option></select></label><label>Format<select v-global-select v-model="reportForm.format"><option>CSV</option><option>XLSX</option><option>PDF</option></select></label><button class="primary" :disabled="busy || !canCreatePage">Buat laporan</button></form><div v-if="reportCreated" class="notice">Job {{ reportCreated.id }} berstatus {{ reportCreated.status }}. Perbarui daftar untuk melihat progres dan unduhan.</div></section><section class="panel"><div class="table-toolbar"><div><h2>Riwayat laporan</h2><p class="muted">Job dan snapshot laporan dalam organisasi Anda.</p></div><button class="secondary" @click="loadRecords('Reports')">Muat ulang</button></div><div class="table-wrap"><table><thead><tr><th>JENIS</th><th>FORMAT</th><th>PERIODE</th><th>STATUS</th><th>DIBUAT</th><th>UNDUH</th></tr></thead><tbody><tr v-for="report in records" :key="report.id"><td>{{ (report as any).type }}</td><td>{{ (report as any).format }}</td><td>{{ ((report as any).filters as any)?.periodStart?.slice(0,10) }} – {{ ((report as any).filters as any)?.periodEnd?.slice(0,10) }}</td><td>{{ report.status }}</td><td>{{ report.createdAt ? new Date(report.createdAt).toLocaleString('id-ID') : '—' }}</td><td><a v-if="report.status==='COMPLETED'" :href="`/api/v1/reports/${report.id}/download`">Unduh {{ (report as any).format }}</a><span v-else>Menunggu</span></td></tr></tbody></table><div v-if="!records.length" class="empty">Belum ada laporan.</div></div></section></section>
<section v-else-if="page === 'Analytics & Forecast'" class="admin-workspace"><form class="panel" @submit.prevent="runForecast"><h2>Forecast Workbench</h2><p class="muted">Pilih model, meter, periode pelatihan, dan horizon. Hasil dapat disimpan untuk perbandingan dan audit.</p><div class="filter-row"><label>Site<select v-global-select v-model="forecastForm.siteId" required @change="forecastForm.meterId='';loadForecastRuns();loadForecastDrivers()"><option value="" disabled>Pilih site</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label><label>Meter (opsional)<select v-global-select v-model="forecastForm.meterId"><option value="">Agregat site</option><option v-for="meter in meters.filter(m=>m.site.id===forecastForm.siteId && m.metric==='ENERGY_IMPORT')" :key="meter.id" :value="meter.id">{{ meter.code }}</option></select></label><label>Model<select v-global-select v-model="forecastForm.model"><option>MOVING_AVERAGE</option><option>EXPONENTIAL_SMOOTHING</option><option>COMPARE</option><option>EXOGENOUS_LINEAR</option></select></label><label v-if="forecastForm.model==='EXPONENTIAL_SMOOTHING'">Alpha<input v-model.number="forecastForm.alpha" type="number" min="0.01" max="1" step="0.01"></label><label>Periode latih (hari)<input v-model.number="forecastForm.days" type="number" min="8" max="365" required></label><label>Horizon (hari)<input v-model.number="forecastForm.horizon" type="number" min="1" max="30" required></label></div><div class="form-actions"><button class="secondary" type="button" :disabled="busy" @click="runForecast">Pratinjau forecast</button><button class="primary" type="button" :disabled="busy || !canCreatePage" @click="saveForecastRun">Simpan forecast run</button></div></form><section v-if="forecastForm.siteId" class="panel forecast-driver-panel"><div class="table-toolbar"><div><h2>Sumber cuaca &amp; produksi</h2><p class="muted">Suhu cuaca dari Open-Meteo memakai koordinat site. Output produksi dapat disimpan per tanggal.</p></div><div class="form-actions"><label>Prakiraan hari<input v-model.number="weatherSyncDays" type="number" min="1" max="15"></label><button class="secondary" type="button" :disabled="busy" @click="syncWeatherDrivers">Sinkronkan Open-Meteo</button></div></div><form class="driver-entry" @submit.prevent="saveForecastDriver"><label>Tanggal<input v-model="forecastDriverForm.date" type="date" required></label><label>Suhu rata-rata (°C)<input v-model="forecastDriverForm.weatherIndex" type="number" min="-100" max="100" step="0.1" placeholder="Opsional"></label><label>Output produksi (unit)<input v-model="forecastDriverForm.productionUnits" type="number" min="0" step="any" placeholder="Opsional"></label><button class="primary" :disabled="busy">Simpan data</button></form><div class="table-wrap"><table><thead><tr><th>TANGGAL SITE</th><th>SUHU RATA-RATA</th><th>OUTPUT PRODUKSI</th><th>SUMBER</th><th>PEMBARUAN</th></tr></thead><tbody><tr v-for="driver in forecastDriverRows" :key="driver.id"><td>{{ String(driver.date).slice(0,10) }}</td><td>{{ driver.weatherIndex ?? "—" }} °C</td><td>{{ driver.productionUnits ?? "—" }}</td><td>{{ driver.source }}</td><td>{{ new Date(driver.updatedAt).toLocaleString() }}</td></tr></tbody></table><div v-if="!forecastDriverRows.length" class="empty">Belum ada data. Sinkronkan cuaca atau tambah output produksi.</div></div></section><section v-if="forecastResult" class="panel"><h2>Hasil forecast · kWh</h2><p class="muted">Pelatihan {{ forecastResult.trainingStart }}–{{ forecastResult.trainingEnd }} UTC · MAE {{ forecastResult.mae }} kWh · MAPE {{ forecastResult.mape == null ? 'tidak tersedia' : forecastResult.mape + '%' }}</p><p class="notice">{{ forecastResult.note }} {{ forecastResult.drivers?.source?.join(", ") }}</p><div class="table-wrap"><table><thead><tr><th>TANGGAL SITE</th><th>PERKIRAAN</th><th>MODEL</th></tr></thead><tbody><tr v-for="point in (forecastResult.forecast || forecastResult.result?.forecast || [])" :key="point.date"><td>{{ point.date }}</td><td>{{ point.kwh }} kWh</td><td>{{ forecastResult.model || forecastForm.model }}</td></tr></tbody></table></div></section><section class="panel"><div class="table-toolbar"><div><h2>Riwayat forecast</h2><p class="muted">Forecast tersimpan termasuk model dan parameter yang digunakan.</p></div><button class="secondary" @click="loadForecastRuns">Muat ulang</button></div><div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>SITE</th><th>METER</th><th>MODEL</th><th>HORIZON</th><th>MAE</th></tr></thead><tbody><tr v-for="run in forecastRuns" :key="run.id"><td>{{ new Date(run.createdAt).toLocaleString('id-ID') }}</td><td>{{ sites.find(s=>s.id===run.siteId)?.name || run.siteId }}</td><td>{{ meters.find(m=>m.id===run.meterId)?.code || 'Agregat' }}</td><td>{{ run.model }}</td><td>{{ (run.parameters as any)?.horizon }} hari</td><td>{{ (run.result as any)?.mae ?? '—' }}</td></tr></tbody></table><div v-if="!forecastRuns.length" class="empty">Belum ada forecast tersimpan.</div></div></section></section><section v-else-if="page === 'Organization Settings'" class="panel settings-card"><form v-if="canCreatePage" @submit.prevent="saveOrganization"><div class="settings-heading"><h2>General information</h2><p class="muted">Perbarui profil organisasi sesuai konfigurasi yang tersedia di FSD.</p></div><label>Nama organisasi *<input v-model="organizationForm.name" required minlength="2" maxlength="200"></label><p class="muted">Perubahan divalidasi oleh server dan dicatat pada audit log.</p><p v-if="error" class="error" role="alert">{{ error }}</p><div class="form-actions"><button class="primary" :disabled="busy">{{ busy ? 'Menyimpan…' : 'Simpan perubahan' }}</button></div></form><div v-else><h2>Organization Settings</h2><p class="muted">Pengaturan organisasi hanya dapat diubah oleh admin.</p></div></section><section v-else-if="recordPages.has(page)" class="panel"><div class="table-toolbar"><div><h2>{{ displayPage }}</h2><p class="muted">{{ descriptions[page] }}</p></div><input v-model="search" class="search module-search" placeholder="Cari data..." aria-label="Cari data"><button v-if="editable.includes(page) && canCreatePage && !['Users','Roles & Permissions','Integrations'].includes(page)" class="primary" @click="startCreate">+ Tambah data {{ displayPage }}</button></div><p v-if="recordPages.has(page) && !endpoints[page]" class="notice">Modul ini belum memiliki alur FSD lengkap; data yang tampil adalah catatan awal, bukan hasil operasional.</p><div v-if="loadingRecords" class="loading-skeleton" role="status" aria-label="Memuat data"><i v-for="n in 4" :key="n"></i></div><div class="table-wrap"><table><thead><tr><th v-for="column in (moduleColumns[page] || [{key:'title',label:'NAMA'},{key:'status',label:'STATUS'},{key:'payload',label:'DETAIL'},{key:'createdAt',label:'DIBUAT'}])" :key="column.key" class="sortable" @click="toggleSort(column.key)">{{ sortedLabel(column.key,column.label) }}</th></tr></thead><tbody><tr v-for="record in pagedRecords" :key="record.id" :class="{clickable: ['Buildings','Assets','Energy Audits','Reports','Alerts'].includes(page)}" @click="['Buildings','Assets','Energy Audits','Reports','Alerts'].includes(page) && openDetail(page,record.id)"><td v-for="column in (moduleColumns[page] || [{key:'title',label:'NAMA'},{key:'status',label:'STATUS'},{key:'payload',label:'DETAIL'},{key:'createdAt',label:'DIBUAT'}])" :key="column.key" :class="{accent: column.key === 'title' || column.key === 'name' || column.key === 'code'}"><span v-if="column.key === 'status'" class="badge">{{ displayCell(record,column.key) }}</span><span v-else>{{ displayCell(record,column.key) }}</span></td></tr></tbody></table><div v-if="!filteredRecords.length" class="empty">{{ search ? 'Tidak ada hasil untuk pencarian ini.' : 'Belum ada data tersedia.' }}</div><div v-if="listPageCount>1" class="form-actions pagination"><button class="secondary" :disabled="currentPage===1" @click="currentPage--">Sebelumnya</button><span>Halaman {{ currentPage }} / {{ listPageCount }}</span><button class="secondary" :disabled="currentPage>=listPageCount" @click="currentPage++">Berikutnya</button></div></div></section>
  <section v-else-if="page === 'Data Quality'" class="panel analysis-results"><div class="table-toolbar"><div><h2>Data Quality</h2><p class="muted">Periksa celah interval, anomali, reset register, dan bacaan di luar rentang.</p></div></div><form class="filter-row" @submit.prevent="loadDataQuality"><label>Site<select v-global-select v-model="dataQualityFilters.siteId"><option value="">Semua site sesuai akses</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label><label>Meter (opsional)<select v-global-select v-model="dataQualityFilters.meterId"><option value="">Semua meter</option><option v-for="meter in meters.filter(x=>!dataQualityFilters.siteId || x.site.id===dataQualityFilters.siteId)" :key="meter.id" :value="meter.id">{{ meter.code }}</option></select></label><label>Hari<input v-model.number="dataQualityFilters.days" type="number" min="1" max="366"></label><button class="primary" :disabled="busy">Periksa data</button></form><div v-if="dataQualityResult" class="kpis"><div class="panel kpi"><span>Bacaan diperiksa</span><strong>{{ dataQualityResult.readingCount }}</strong></div><div class="panel kpi"><span>Temuan</span><strong>{{ dataQualityResult.issueCount }}</strong></div><div class="panel kpi"><span>Critical</span><strong>{{ dataQualityResult.counts.CRITICAL }}</strong></div><div class="panel kpi"><span>Warning</span><strong>{{ dataQualityResult.counts.WARNING }}</strong></div></div><div class="table-wrap" v-if="dataQualityResult"><table><thead><tr><th>WAKTU</th><th>METER</th><th>JENIS</th><th>SEVERITY</th><th>DETAIL</th></tr></thead><tbody><tr v-for="issue in dataQualityResult.issues" :key="issue.id || `${issue.meterCode}-${issue.timestamp}-${issue.code}`"><td>{{ issue.timestamp ? new Date(issue.timestamp).toLocaleString('id-ID') : '—' }}</td><td>{{ issue.meterCode || issue.meterId }}</td><td>{{ issue.code || issue.type }}</td><td><span class="badge">{{ issue.severity }}</span></td><td>{{ issue.message || issue.description }}</td></tr></tbody></table><div v-if="!dataQualityResult.issues.length" class="empty">Tidak ditemukan masalah pada rentang ini.</div></div></section>
<section v-else-if="page === 'Notifications'" class="notification-layout"><section class="panel import-panel"><h2>Preferensi notifikasi</h2><form @submit.prevent="saveNotificationPreferences"><label class="check-row"><input v-model="notificationPreferences.inAppEnabled" type="checkbox">Notifikasi dalam aplikasi</label><label class="check-row"><input v-model="notificationPreferences.emailEnabled" type="checkbox">Email (tergantung konfigurasi gateway)</label><p v-if="authNotice" class="notice">{{ authNotice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary" :disabled="busy">Simpan preferensi</button></form></section><section class="panel import-panel"><h2>Riwayat pengiriman</h2><div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>KANAL</th><th>STATUS</th><th>ALERT</th><th>ERROR</th></tr></thead><tbody><tr v-for="delivery in notificationDeliveries" :key="delivery.id"><td>{{ new Date(delivery.createdAt).toLocaleString('id-ID') }}</td><td>{{ delivery.channel }}</td><td>{{ delivery.status }}</td><td>{{ delivery.alert?.message || delivery.alertId }}</td><td>{{ delivery.lastError || '—' }}</td></tr></tbody></table><div v-if="!notificationDeliveries.length" class="empty">Belum ada pengiriman notifikasi.</div></div></section></section>
<DataSources v-else-if="page === 'Data Sources'" :csrf-token="user.csrfToken" :can-manage="workspaceStore.hasAnyPermission(['integrations.manage'])" /><section v-else-if="page === 'My Profile'" class="panel settings-card"><form @submit.prevent="saveProfile"><h2>Profil saya</h2><label>Nama lengkap<input v-model="profileForm.fullName" minlength="2" maxlength="150" required></label><label>Email<input :value="user.email" type="email" disabled></label><p v-if="authNotice" class="notice">{{ authNotice }}</p><button class="primary">Simpan profil</button></form><form class="profile-password" @submit.prevent="changePassword"><h2>Ubah kata sandi</h2><label>Kata sandi saat ini<input v-model="passwordForm.currentPassword" type="password" required autocomplete="current-password"></label><label>Kata sandi baru<input v-model="passwordForm.newPassword" type="password" minlength="12" maxlength="200" required autocomplete="new-password"></label><label>Ulangi kata sandi baru<input v-model="passwordForm.confirm" type="password" minlength="12" required autocomplete="new-password"></label><button class="secondary" :disabled="busy">Ubah kata sandi dan keluar dari sesi lain</button></form></section>
<section v-else-if="page === 'Users'" class="admin-workspace users-workspace">
<section class="panel"><div class="table-toolbar users-toolbar"><div><h2>Anggota organisasi</h2><p class="muted">Undangan, role, status akun, dan site assignment.</p></div><input v-model="search" class="search" type="search" maxlength="200" placeholder="Cari nama atau email" aria-label="Cari pengguna"><button class="primary" @click="inviteForm={email:'',fullName:'',roleId:'',siteIds:[]};showForm=true">Undang pengguna</button></div>
<p v-if="loadingRecords" class="muted users-loading" role="status">Memuat anggota organisasi…</p><div class="table-wrap"><table v-if="!loadingRecords"><thead><tr><th class="sortable" @click="toggleSort('fullName')">NAMA / EMAIL {{ sortedLabel('fullName','') }}</th><th class="sortable" @click="toggleSort('role')">ROLE {{ sortedLabel('role','') }}</th><th>SITE ASSIGNMENT</th><th>AKTIF</th><th></th></tr></thead><tbody><tr v-for="member in users" :key="member.id"><td><strong>{{ member.fullName }}</strong><small>{{ member.email }}</small></td><td><select v-global-select v-model="memberDrafts[member.id].roleId"><option v-for="role in roles" :key="role.id" :value="role.id">{{ role.name }}</option></select></td><td><div class="user-site-assignments"><label v-for="site in sites" :key="site.id" class="check-row"><input v-model="memberDrafts[member.id].siteIds" type="checkbox" :value="site.id">{{ site.name }}</label></div></td><td><input v-model="memberDrafts[member.id].active" type="checkbox" :aria-label="`Status ${member.email}`"></td><td><button class="secondary" @click="saveMember(member.id)">Simpan</button></td></tr></tbody></table><div v-if="!users.length && !loadingRecords" class="empty">{{ search ? 'Tidak ada pengguna yang cocok dengan pencarian.' : 'Belum ada anggota organisasi.' }}</div></div>
<div class="form-actions pagination users-pagination"><span>{{ serverRecordCount }} anggota · halaman {{ currentPage }} dari {{ listPageCount }}</span><button class="secondary" :disabled="currentPage<=1 || loadingRecords" @click="currentPage--">Sebelumnya</button><button class="secondary" :disabled="currentPage>=listPageCount || loadingRecords" @click="currentPage++">Berikutnya</button></div></section>
<section class="panel users-invitations"><div class="table-toolbar"><div><h2>Undangan</h2><p class="muted">Tautan undangan kedaluwarsa setelah 24 jam.</p></div></div><div v-if="newInvitationUrl" class="notice users-invitation-notice"><div><strong>Email gateway belum digunakan; salin tautan ini dan kirimkan kepada undangan.</strong><input :value="newInvitationUrl" readonly></div><button class="secondary" @click="copySecret(newInvitationUrl)">Salin tautan</button><button class="secondary" @click="newInvitationUrl=''">Tutup</button></div><div class="table-wrap"><table><thead><tr><th>NAMA / EMAIL</th><th>ROLE</th><th>EXPIRED</th><th>STATUS</th></tr></thead><tbody><tr v-for="invitation in invitations" :key="invitation.id"><td><strong>{{ invitation.fullName }}</strong><small>{{ invitation.email }}</small></td><td>{{ invitation.roleName }}</td><td>{{ new Date(invitation.expiresAt).toLocaleString('id-ID') }}</td><td>{{ invitation.acceptedAt ? 'Diterima' : invitation.revokedAt ? 'Dicabut' : 'Menunggu' }}</td></tr></tbody></table><div v-if="!invitations.length" class="empty">Belum ada undangan aktif.</div></div></section></section>
<section v-else-if="page === 'Roles & Permissions'" class="admin-workspace"><section class="panel"><div class="table-toolbar"><div><h2>Roles & Permissions</h2><p class="muted">Role sistem dan role khusus organisasi. Perubahan tercatat di audit log.</p></div><button class="primary" @click="roleForm={name:'',description:'',scope:'ASSIGNED_SITES',permissionCodes:[]};showForm=true">Buat role</button></div><article v-for="role in roles" :key="role.id" class="role-card"><div class="table-toolbar"><div><h3>{{ role.name }} <span class="badge">{{ role.scope }}</span></h3><p class="muted">{{ role.description || '—' }} · {{ role._count?.memberships || 0 }} anggota</p></div><button v-if="!role.isSystem" class="secondary" @click="saveRolePermissions(role)">Simpan permission</button></div><div class="permission-grid"><label v-for="permission in permissionCatalog" :key="permission.code" class="check-row"><input v-model="role.selectedPermissionCodes" type="checkbox" :value="permission.code">{{ permission.code }}</label></div></article></section></section>
<section v-else-if="page === 'Integrations'" class="panel"><div class="table-toolbar"><div><h2>API integrations</h2><p class="muted">Kunci mentah hanya ditampilkan sekali setelah dibuat atau dirotasi.</p></div><button class="primary" @click="integrationModalType='API';integrationForm={name:'',meterIds:[],ipAllowlist:'',rateLimitPerMinute:60};showForm=true">Buat API key</button></div><button class="secondary" @click="integrationModalType='WEBHOOK';webhookForm={name:'',url:'',events:['alert.created']};showForm=true">Tambah webhook</button><div v-if="newIntegrationToken" class="notice secret-notice"><strong>Salin token sekarang; token tidak dapat dibaca kembali.</strong><input :value="newIntegrationToken" readonly><button class="secondary" @click="copySecret(newIntegrationToken)">Salin token</button><button class="secondary" @click="newIntegrationToken=''">Tutup</button></div><div class="table-wrap"><table><thead><tr><th>NAMA</th><th>METER DIIZINKAN</th><th>IP ALLOWLIST</th><th>RATE / MENIT</th><th>STATUS</th><th>AKSI</th></tr></thead><tbody><tr v-for="source in records" :key="source.id"><td>{{ (source as any).name }}</td><td>{{ ((source as any).allowedMeterIds || []).length }}</td><td>{{ ((source as any).allowedIpAddresses || []).join(', ') || 'Semua' }}</td><td>{{ (source as any).rateLimitPerMinute }}</td><td>{{ source.status }}</td><td><button v-if="source.status==='ACTIVE'" class="secondary" @click="rotateIntegration(source.id)">Rotate</button><button v-if="source.status==='ACTIVE'" class="danger-button" @click="revokeIntegration(source.id)">Revoke</button></td></tr></tbody></table><div v-if="!records.length" class="empty">Belum ada sumber integrasi.</div></div><section class="panel"><div class="table-toolbar"><div><h2>Webhook</h2><p class="muted">Endpoint HTTPS publik. Secret mentah hanya ditampilkan sekali.</p></div></div><div v-if="newWebhookSecret" class="notice secret-notice"><strong>Simpan secret ini sekarang; tidak dapat dibaca kembali.</strong><input :value="newWebhookSecret" readonly><button class="secondary" @click="copySecret(newWebhookSecret)">Salin secret</button><button class="secondary" @click="newWebhookSecret=''">Tutup</button></div><div v-if="authNotice" class="notice">{{ authNotice }}</div><div class="table-wrap"><table><thead><tr><th>NAMA / URL</th><th>EVENT</th><th>STATUS</th><th>DELIVERY</th><th>AKSI</th></tr></thead><tbody><tr v-for="hook in webhooks" :key="hook.id"><td>{{ hook.name }}<br><small>{{ hook.url }}</small></td><td>{{ hook.events.join(', ') }}</td><td>{{ hook.status }}</td><td>{{ hook.lastDeliveredAt ? new Date(hook.lastDeliveredAt).toLocaleString('id-ID') : 'Belum pernah' }}<button class="secondary" @click="loadWebhookDeliveries(hook.id)">Riwayat</button><small v-for="delivery in webhookDeliveries[hook.id] || []" :key="delivery.id" class="detail-row">{{ delivery.event }} · {{ delivery.status }} · {{ delivery.responseCode || delivery.error }}</small></td><td><button v-if="hook.status==='ACTIVE'" class="secondary" @click="testWebhook(hook.id)">Test</button><button v-if="hook.status==='ACTIVE'" class="secondary" @click="rotateWebhook(hook.id)">Rotate secret</button><button v-if="hook.status==='ACTIVE'" class="danger-button" @click="revokeWebhook(hook.id)">Revoke</button></td></tr></tbody></table><div v-if="!webhooks.length" class="empty">Belum ada webhook.</div></div></section></section><section v-else-if="page === 'Audit Logs'" class="panel"><div class="table-toolbar"><div><h2>Audit log organisasi</h2><p class="muted">Riwayat aktivitas terbaru, maksimum 100 catatan.</p></div><button class="secondary" @click="loadRecords('Audit Logs')">Muat ulang</button></div><div class="table-wrap"><table v-if="records.length"><thead><tr><th>WAKTU</th><th>PENGGUNA</th><th>AKSI</th><th>ENTITAS</th><th>ID ENTITAS</th><th>DETAIL</th></tr></thead><tbody><tr v-for="log in records" :key="log.id"><td>{{ log.createdAt ? new Date(log.createdAt).toLocaleString('id-ID') : '—' }}</td><td>{{ (log as any).userId || 'Sistem' }}</td><td><span class="badge">{{ (log as any).action }}</span></td><td>{{ (log as any).entity }}</td><td>{{ (log as any).entityId || '—' }}</td><td>{{ (log as any).details ? JSON.stringify((log as any).details) : '—' }}</td></tr></tbody></table><div v-else class="empty">Belum ada catatan audit untuk organisasi ini.</div></div></section>
  <section v-else-if="page === 'Monitoring' || page === 'Monitoring History'" class="monitoring-page"><form class="panel filter-row" @submit.prevent="loadMonitoringData"><label>Site<select v-global-select v-model="monitorFilters.siteId"><option value="">Semua site sesuai hak akses</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select></label><label>Gedung<select v-global-select v-model="monitorFilters.buildingId"><option value="">Semua gedung</option><option v-for="building in buildings.filter(b=>!monitorFilters.siteId || b.siteId===monitorFilters.siteId)" :key="building.id" :value="building.id">{{ building.name }}</option></select></label><label>Meter<select v-global-select v-model="monitorFilters.meterId"><option value="">Semua meter</option><option v-for="meter in meters.filter(m=>(!monitorFilters.siteId || m.site.id===monitorFilters.siteId) && m.metric===monitorFilters.metric)" :key="meter.id" :value="meter.id">{{ meter.code }}</option></select></label><label>Hari<input v-model.number="monitorFilters.days" type="number" min="1" max="365"></label><label>Metrik<select v-global-select v-model="monitorFilters.metric"><option>ENERGY_IMPORT</option><option>POWER_DEMAND</option></select></label><label>Bucket<select v-global-select v-model="monitorFilters.bucket"><option>HOUR</option><option>DAY</option><option>WEEK</option><option>MONTH</option></select></label><label class="check-row"><input v-model="monitorFilters.comparePrevious" type="checkbox">Bandingkan periode sebelumnya</label><button class="primary" :disabled="busy">Terapkan filter</button></form><div class="kpis"><div class="panel kpi"><span>{{ monitorFilters.metric==='POWER_DEMAND'?'Puncak demand':'Energi tervalidasi' }} · {{ monitorFilters.days }} hari</span><strong>{{ monitorFilters.metric==='POWER_DEMAND'?(summary?.peakDemandKw ?? '—'):(summary?.energyKwh ?? '—') }} {{ seriesUnit }}</strong><small>Dari bacaan meter valid</small></div><div class="panel kpi"><span>Site terhubung</span><strong>{{ summary?.siteCount ?? sites.length }}</strong><small>Dalam cakupan akses Anda</small></div><div class="panel kpi"><span>Meter terdaftar</span><strong>{{ summary?.meterCount ?? meters.length }}</strong><small>Semua status meter</small></div><div class="panel kpi"><span>Alert terbuka</span><strong>{{ summary?.openAlerts ?? '—' }}</strong><small>Insiden aktif</small></div></div><div v-if="summary?.comparison" class="notice comparison-notice">Periode sebelumnya ({{ new Date(summary.comparison.periodStart).toLocaleDateString('id-ID') }}–{{ new Date(summary.comparison.periodEnd).toLocaleDateString('id-ID') }}): perubahan {{ summary.comparison.metricChangePercent == null ? '—' : `${summary.comparison.metricChangePercent > 0 ? '+' : ''}${summary.comparison.metricChangePercent}%` }}.</div><section class="panel chart-panel"><div class="chart-heading"><div><h2>{{ page === 'Monitoring' ? 'Monitoring live · ' + seriesUnit : 'Riwayat energi dan demand' }}</h2><p class="muted">Metrik {{ monitorFilters.metric }} · agregasi {{ monitorFilters.bucket }} · data tervalidasi</p></div><span class="range-chip">{{ monitorFilters.days }} hari · {{ monitorFilters.bucket }} · {{ summary?.timezone || 'UTC' }}</span></div><div class="empty-chart"><EnergyChart v-if="series.length" :dates="series.map(point => point.date)" :values="series.map(point => point.kwh)" :unit="seriesUnit" /><span v-if="!series.length">Belum ada data konsumsi untuk periode ini.</span></div></section><section class="panel"><div class="table-toolbar"><div><h2>{{ page === 'Monitoring' ? 'Meter aktif' : 'Rincian konsumsi harian' }}</h2><p class="muted">{{ page === 'Monitoring' ? 'Bacaan terakhir per meter' : 'Nilai aktual dari rangkaian waktu' }}</p></div></div><div class="table-wrap"><table v-if="page === 'Monitoring'"><thead><tr><th>METER</th><th>SITE</th><th>METRIK</th><th>BACAAN TERAKHIR</th><th>WAKTU</th><th>KUALITAS</th></tr></thead><tbody><tr v-for="meter in meters" :key="meter.id" class="clickable" @click="openDetail('Meters',meter.id)"><td class="accent">{{ meter.code }}</td><td>{{ meter.site.name }}</td><td>{{ meter.metric === 'POWER_DEMAND' ? 'Demand' : 'Energy' }}</td><td>{{ meter.readings[0] ? `${meter.readings[0].value} ${meter.readings[0].unit}` : '—' }}</td><td>{{ meter.readings[0] ? new Date(meter.readings[0].timestamp).toLocaleString('id-ID',{timeZone:meter.site.timezone}) : '—' }}</td><td><span v-if="meter.readings[0]" class="badge">{{ meter.readings[0].quality }}</span><span v-else>—</span></td></tr></tbody></table><table v-else><thead><tr><th>TANGGAL</th><th>{{ seriesUnit }}</th></tr></thead><tbody><tr v-for="point in series" :key="point.date"><td>{{ point.date }}</td><td>{{ point.kwh.toLocaleString('id-ID') }}</td></tr></tbody></table><div v-if="page === 'Monitoring' ? !meters.length : !series.length" class="empty">Belum ada data untuk ditampilkan.</div></div></section></section><section v-else-if="recordPages.has(page)" class="panel module-workspace"><div class="table-toolbar"><div><h2>{{ displayPage }}</h2><p class="muted">{{ descriptions[page] || 'Data dan konfigurasi organisasi.' }}</p></div><input v-model="search" class="search" :placeholder="`Cari ${displayPage.toLowerCase()}...`" :aria-label="`Cari ${displayPage}`"></div><div class="table-wrap"><table v-if="filteredRecords.length && moduleColumns[page]?.length"><thead><tr><th v-for="column in moduleColumns[page]" :key="column.key" class="sortable" @click="toggleSort(column.key)">{{ sortedLabel(column.key,column.label) }}</th></tr></thead><tbody><tr v-for="record in pagedRecords" :key="record.id" :class="{clickable: page === 'Assets'}" @click="page === 'Assets' && openDetail('Assets',record.id)"><td v-for="column in moduleColumns[page]" :key="column.key">{{ displayCell(record,column.key) }}</td></tr></tbody></table><div v-else class="empty">{{ records.length ? 'Belum ada data yang cocok dengan pencarian.' : 'Belum ada data untuk ditampilkan.' }}</div></div></section><section v-else class="panel unavailable"><h2>{{ displayPage }}</h2><p class="muted">{{ descriptions[page] || 'Pilih modul dari menu untuk melihat data organisasi.' }}</p></section>
  </div><template #overlay><div v-if="showForm" :class="['modal-backdrop', { 'new-meter-flow': route.path === '/meters/new' }]" @click.self="closeForm"><section class="modal" role="dialog" aria-modal="true" :aria-label="route.path === '/meters/new' ? 'New Meter' : `Tambah ${page}`"><div class="modal-heading"><h2>{{ route.path === '/meters/new' ? 'New Meter' : editingSite ? 'Edit site' : `Tambah ${page}` }}</h2><button class="icon-button" @click="closeForm" aria-label="Tutup">×</button></div><form @submit.prevent="page === 'Users' ? inviteUser() : page === 'Roles & Permissions' ? saveRole() : page === 'Integrations' ? (integrationModalType === 'WEBHOOK' ? createWebhook() : createIntegration()) : page === 'Meters' && detail ? saveMeterConfiguration() : page === 'Data Imports' && quarantineForm.id ? releaseQuarantine() : page === 'Meter Maintenance' ? createMaintenance() : recordPages.has(page) ? saveRecord() : save()"><template v-if="page === 'Data Imports' && quarantineForm.id"><p class="muted">Periksa dan koreksi data sumber karantina sebelum disimpan sebagai bacaan tervalidasi.</p><label>Meter tujuan<select v-global-select v-model="quarantineForm.meterId" required><option value="" disabled>Pilih meter aktif</option><option v-for="meter in meters.filter(m=>m.status!=='RETIRED')" :key="meter.id" :value="meter.id">{{ meter.code }} · {{ meter.site.name }}</option></select></label><label>Timestamp ISO 8601<input v-model="quarantineForm.timestamp" type="datetime-local" required></label><label>Nilai<input v-model="quarantineForm.value" type="number" min="0" step="any" required></label><label>Unit<select v-global-select v-model="quarantineForm.unit"><option>kWh</option><option>kW</option></select></label></template><template v-if="page === 'Meter Maintenance'"><label>Kategori<select v-global-select v-model="maintenanceForm.category"><option>PREVENTIVE</option><option>CORRECTIVE</option><option>CALIBRATION</option><option>INSPECTION</option></select></label><label>Judul pekerjaan<input v-model="maintenanceForm.title" required minlength="2" maxlength="200"></label><label>Jadwal<input v-model="maintenanceForm.scheduledAt" type="datetime-local"></label><label>Penanggung jawab UUID (opsional)<input v-model="maintenanceForm.assignedTo" placeholder="UUID anggota site"></label></template><template v-if="page === 'Meters' && detail"><label>Sumber<select v-global-select v-model="configForm.sourceType"><option>MANUAL</option><option>CSV</option><option>API</option><option>SIMULATOR</option><option>MQTT</option></select></label><label>Interval menit<input v-model.number="configForm.intervalMinutes" type="number" min="1" max="60" required></label><label>Multiplier<input v-model.number="configForm.multiplier" type="number" min="0.000001" step="any" required></label><label>Rollover (opsional)<input v-model="configForm.rolloverValue" type="number" min="0" step="any"></label><label>Efektif mulai<input v-model="configForm.effectiveFrom" type="datetime-local" required></label><label>Alasan perubahan<input v-model="configForm.reason" required minlength="2"></label></template><template v-if="page === 'Sites'"><label>Kode site *<input v-model="siteForm.code" required pattern="[A-Z0-9-]+" placeholder="SITE-JKT-01"></label><label>Nama site *<input v-model="siteForm.name" required minlength="2"></label><label>Tipe site *<select v-global-select v-model="siteForm.type"><option>FACTORY</option><option>OFFICE</option><option>COMMERCIAL</option><option>WAREHOUSE</option><option>OTHER</option></select></label><label>Alamat *<textarea v-model="siteForm.address" required minlength="10"></textarea></label><label>Zona waktu *<select v-global-select v-model="siteForm.timezone"><option>Asia/Jakarta</option><option>Asia/Makassar</option><option>Asia/Jayapura</option></select></label><label>Wilayah emisi (opsional)<input v-model="siteForm.emissionRegion" placeholder="Indonesia"></label><label>Latitude (opsional)<input v-model="siteForm.latitude" type="number" min="-90" max="90" step="any"></label><label>Longitude (opsional)<input v-model="siteForm.longitude" type="number" min="-180" max="180" step="any"></label><label>Site manager (opsional)<select v-global-select v-model="siteForm.managerId"><option value="">Tidak ditetapkan</option><option v-for="member in users" :key="member.id" :value="member.id">{{ member.fullName }}</option></select></label><label v-if="editingSite">Status<select v-global-select v-model="siteForm.status"><option>ACTIVE</option><option>INACTIVE</option></select></label></template><template v-else-if="page === 'Meters'"><label>Kode meter *<input v-model="meterForm.code" required></label><label>Site *<select v-global-select v-model="meterForm.siteId" required @change="meterForm.assetId = ''"><option value="" disabled>Pilih site</option><option v-for="s in sites" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label>Tipe meter *<select v-global-select v-model="meterForm.meterType"><option>CUMULATIVE</option><option>INTERVAL</option></select></label><label>Metrik *<select v-global-select v-model="meterForm.metric" @change="meterForm.unit = meterForm.metric === 'ENERGY_IMPORT' ? 'kWh' : 'kW'"><option>ENERGY_IMPORT</option><option>POWER_DEMAND</option></select></label><label>Sumber *<select v-global-select v-model="meterForm.sourceType"><option>MANUAL</option><option>CSV</option><option>API</option><option>SIMULATOR</option><option>MQTT</option></select></label><label>Interval (menit) *<select v-global-select v-model.number="meterForm.intervalMinutes"><option v-for="n in [1,5,15,30,60]" :key="n" :value="n">{{ n }}</option></select></label><label>Multiplier *<input v-model.number="meterForm.multiplier" type="number" min="0.000001" step="any" required></label><label>Nomor seri (opsional)<input v-model="meterForm.serialNumber"></label><label>Asset (opsional)<select v-global-select v-model="meterForm.assetId"><option value="">Tanpa asset</option><option v-for="asset in meterAssets.filter(a=>a.siteId===meterForm.siteId)" :key="asset.id" :value="asset.id">{{ asset.code }} · {{ asset.name }}</option></select></label><label>Tanggal pemasangan (opsional)<input v-model="meterForm.installedAt" type="datetime-local"></label><label>Register rollover (opsional)<input v-model="meterForm.rolloverValue" type="number" min="0.000001" step="any"></label></template><template v-else-if="page === 'Assets'"><label>Kode aset *<input v-model="assetForm.code" required></label><label>Nama aset *<input v-model="assetForm.name" required minlength="2"></label><label>Tipe aset *<input v-model="assetForm.type" required minlength="2"></label><label>Site *<select v-global-select v-model="assetForm.siteId" required><option value="" disabled>Pilih site</option><option v-for="s in sites" :key="s.id" :value="s.id">{{ s.name }}</option></select></label></template><template v-else-if="page === 'Alert Rules'"><label>Nama aturan<input v-model="recordForm.name" required minlength="2"></label><label>Cakupan<select v-global-select v-model="recordForm.scopeType" required @change="recordForm.scopeId = ''"><option value="" disabled>Pilih cakupan</option><option value="SITE">Site</option><option value="METER">Meter</option></select></label><label>Site atau meter<select v-global-select v-model="recordForm.scopeId" required><option value="" disabled>Pilih cakupan</option><template v-if="recordForm.scopeType === 'SITE'"><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></template><template v-else-if="recordForm.scopeType === 'METER'"><option v-for="meter in meters" :key="meter.id" :value="meter.id">{{ meter.code }} · {{ meter.site.name }}</option></template></select></label><label>Metrik<select v-global-select v-model="recordForm.metric" required><option value="" disabled>Pilih metrik</option><option>ENERGY_IMPORT</option><option>POWER_DEMAND</option></select></label><label>Operator<select v-global-select v-model="recordForm.operator" required><option value="" disabled>Pilih operator</option><option>GT</option><option>LT</option><option>OUTSIDE_RANGE</option></select></label><label>Ambang minimum<input v-model="recordForm.threshold" type="number" min="0" step="0.0001" required></label><label v-if="recordForm.operator === 'OUTSIDE_RANGE'">Ambang maksimum<input v-model="recordForm.thresholdMax" type="number" min="0" step="0.0001" required></label><label>Jendela (menit)<input v-model="recordForm.windowMinutes" type="number" min="1" max="1440" required></label><label>Cooldown (menit)<input v-model="recordForm.cooldownMinutes" type="number" min="0" max="10080" required></label><label>Severity<select v-global-select v-model="recordForm.severity" required><option value="" disabled>Pilih severity</option><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select></label><fieldset><legend>Kanal notifikasi</legend><label class="check-row"><input v-model="recordForm.channels" type="checkbox" value="IN_APP">Dalam aplikasi</label><label class="check-row"><input v-model="recordForm.channels" type="checkbox" value="EMAIL">Email (gateway email harus dikonfigurasi)</label></fieldset></template><template v-else-if="page === 'Users'"><label>Email undangan<input v-model="inviteForm.email" type="email" required maxlength="254"></label><label>Nama lengkap<input v-model="inviteForm.fullName" required minlength="2" maxlength="150"></label><label>Role organisasi<select v-global-select v-model="inviteForm.roleId" required><option value="" disabled>Pilih role</option><option v-for="role in roles.filter(r=>r.active)" :key="role.id" :value="role.id">{{ role.name }} · {{ role.scope }}</option></select></label><fieldset><legend>Site assignment</legend><label v-for="site in sites" :key="site.id" class="check-row"><input v-model="inviteForm.siteIds" type="checkbox" :value="site.id">{{ site.name }}</label></fieldset></template><template v-else-if="page === 'Roles & Permissions'"><label>Nama role<input v-model="roleForm.name" required minlength="2" maxlength="100"></label><label>Deskripsi<input v-model="roleForm.description" maxlength="500"></label><label>Scope<select v-global-select v-model="roleForm.scope"><option>ASSIGNED_SITES</option><option>ORGANIZATION</option></select></label><fieldset><legend>Permissions</legend><label v-for="permission in permissionCatalog" :key="permission.code" class="check-row"><input v-model="roleForm.permissionCodes" type="checkbox" :value="permission.code">{{ permission.code }} — {{ permission.description }}</label></fieldset></template><template v-else-if="page === 'Integrations' && integrationModalType === 'WEBHOOK'"><label>Nama webhook<input v-model="webhookForm.name" required minlength="2" maxlength="120"></label><label>URL tujuan HTTPS<input v-model="webhookForm.url" type="url" required placeholder="https://example.com/webhook"></label><fieldset><legend>Event</legend><label v-for="eventName in ['alert.created','alert.updated','reading.import.completed','report.completed']" :key="eventName" class="check-row"><input v-model="webhookForm.events" type="checkbox" :value="eventName">{{ eventName }}</label></fieldset></template><template v-else-if="page === 'Integrations' && integrationModalType === 'API'"><label>Nama sumber<input v-model="integrationForm.name" required minlength="2" maxlength="100"></label><fieldset><legend>Meter yang diizinkan</legend><label v-for="meter in meters" :key="meter.id" class="check-row"><input v-model="integrationForm.meterIds" type="checkbox" :value="meter.id">{{ meter.code }} · {{ meter.site.name }}</label></fieldset><label>IP allowlist (pisahkan koma/baris baru)<textarea v-model="integrationForm.ipAllowlist" placeholder="192.0.2.10"></textarea></label><label>Rate limit per menit<input v-model.number="integrationForm.rateLimitPerMinute" type="number" min="1" max="100000" required></label></template><template v-else-if="domainFields[page]"><template v-for="field in domainFields[page]" :key="field.key"><label v-if="!(page === 'Buildings' && editingRecordId && field.key === 'siteId')">{{ field.label }}<select v-global-select v-if="field.type === 'site'" v-model="recordForm[field.key]" required><option value="" disabled>Pilih site</option><option v-for="site in sites" :key="site.id" :value="site.id">{{ site.name }}</option></select><select v-global-select v-else-if="field.type === 'status'" v-model="recordForm[field.key]"><option>ACTIVE</option><option>INACTIVE</option><option v-if="editingRecordId">ARCHIVED</option></select><input v-else v-model="recordForm[field.key]" :type="field.type || 'text'" :step="field.type === 'number' ? 'any' : undefined" :required="!field.label.includes('(opsional)')"></label></template></template><template v-else><p class="muted">Formulir khusus untuk modul ini belum tersedia.</p></template><p v-if="error" class="error" role="alert">{{ error }}</p><div class="form-actions"><button type="button" class="secondary" @click="closeForm">Batal</button><button class="primary" :disabled="busy">Simpan</button></div></form></section></div></template></WorkspaceLayout>
</template>
